// 위 BRANCH_MANAGER_MAP은 SUBSCRIPTION_DATA 전용으로 손으로 옮겨 적었던 legacy branchId
// ('b01' 등) 기준이라, 실제 DB.branches[].id(ensureBranch가 만드는 br_지점명_랜덤 형식)와는
// 전혀 매칭되지 않아 관리자별 집계가 항상 "미지정"으로 빠지는 문제가 있었다. 지점"명" 기준으로
// 한 번 더 매핑을 만들어 두면 실제 지점 레코드와 안정적으로 매칭된다. 다만 이것도 어디까지나
// 최초 1회용 폴백일 뿐이고, 목표 파일이 업로드되면 그 시점부터 branch.manager가 파일의 SR로
// 매달 자동 갱신되므로(applyGoalsFileUpload 참고) 그게 항상 가장 정확한 최신 출처다.
const BRANCH_MANAGER_BY_NAME = (function(){
  const map = {};
  ((SUBSCRIPTION_DATA.emart && SUBSCRIPTION_DATA.emart.groups) || []).forEach(grp=>{
    (grp.branches||[]).forEach(b=>{
      const nm = String(b.name||'').replace(/^\(신\)\s*이마트\s*/, '').trim();
      if(nm) map[nm] = grp.manager;
    });
  });
  return map;
})();

/* =========================================================================
   1a2. SHARED DB (Supabase) — 전체 팀 실시간 공유 저장소
   여러 지점 매니저/직원이 각자 기기에서 동시에 접속해 같은 데이터를 보고
   쓸 수 있도록, 앱 전체 DB(JSON 한 덩어리)를 Supabase의 kpi_db 테이블
   (id=1 고정 행, data jsonb 컬럼)에 저장한다. 나머지 앱 코드는 그대로
   메모리상의 DB 객체를 동기적으로 읽고/쓰고, saveDB()만 백그라운드로
   서버에 반영하는 방식이라 기존 기능 로직은 전혀 바뀌지 않는다.
   ========================================================================= */
const SUPABASE_URL = 'https://qxqyfxtvyktvqvoqfwvg.supabase.co';
const SUPABASE_KEY = 'sb_publishable_SAI8HjfxaQ1JiJTIAVOsIA_N2WY8TI0';
let sbClient = null;
try{
  if(typeof window !== 'undefined' && window.supabase && typeof window.supabase.createClient === 'function'){
    sbClient = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY);
  }
}catch(e){ console.error('Supabase 클라이언트 초기화 실패:', e); }

let DB = null;
let DB_VERSION = 0;
// 마지막으로 서버와 100% 일치했던 시점의 스냅샷("3-way 병합"의 공통 기준점). 저장 충돌이나
// 백그라운드 폴링으로 서버 최신본을 받아올 때, 로컬 DB를 이 기준점과 비교해서 "내가 방금
// 새로 추가/수정한 항목"이 무엇인지 구분해내는 데 쓴다 - 그래야 서버 최신본과 병합할 때
// 그 변경분을 통째로 잃어버리지 않는다.
let DB_BASELINE = null;
let dbReady = false;
let dbPollTimer = null;

function cacheDBLocally(){
  try{ localStorage.setItem(STORAGE_KEY, JSON.stringify(DB)); }catch(e){ /* 저장공간 부족 등은 무시 */ }
}
function cloneDBSnapshot(obj){
  try{ return JSON.parse(JSON.stringify(obj)); }catch(e){ return obj; }
}

/* -------------------------------------------------------------------------
   여러 매니저가 각자 다른 항목을 거의 동시에 등록/수정하면 저장 버전이 어긋난다.
   예전에는 이때 "최신 버전 번호"만 다시 읽어와서 로컬 DB(오래된 스냅샷 기준으로 통째로
   들고 있던 것)를 그 번호로 그대로 재전송했다 - 그런데 이러면 그 사이 다른 사람이 새로
   등록한 내용이 함께 들어있는 서버 데이터를, 그 내용을 전혀 모르는 내 로컬 DB로 조용히
   덮어써버리는 사고가 났다(저장은 에러 없이 "성공"하기 때문에 아무도 눈치채지 못하고,
   나중에 "분명히 등록했는데 사라졌다"는 문의로만 드러났다).

   아래 mergeRemoteDB()는 "마지막으로 서버와 일치했던 시점(DB_BASELINE)"을 기준으로 3-way
   병합을 수행한다: id가 있는 배열(등록형 목록 - 실행력 점검 사진, 상품권/사은품 취합,
   공지/게시글, 가망고객 등)은 항목 단위로 합쳐서 "내가 새로 추가한 것"과 "상대가 새로
   추가한 것"이 모두 남도록 하고, 어느 한쪽에서 삭제한 항목은 삭제된 채로 유지한다.
   id가 없는 필드(설정성 데이터)는 기준점 대비 실제로 바뀐 쪽의 값을 우선한다.
------------------------------------------------------------------------- */
function isIdKeyedArray(arr){
  return Array.isArray(arr) && arr.length>0 && arr.every(x=>x && typeof x==='object' && !Array.isArray(x) && x.id!=null);
}
function mergeIdArray(baseArr, localArr, remoteArr){
  const baseMap = new Map((baseArr||[]).map(x=>[x.id, x]));
  const localMap = new Map((localArr||[]).map(x=>[x.id, x]));
  const remoteMap = new Map((remoteArr||[]).map(x=>[x.id, x]));
  const order = []; const seen = new Set();
  (remoteArr||[]).forEach(x=>{ if(!seen.has(x.id)){ order.push(x.id); seen.add(x.id); } });
  (localArr||[]).forEach(x=>{ if(!seen.has(x.id)){ order.push(x.id); seen.add(x.id); } });
  const result = [];
  order.forEach(id=>{
    const inBase = baseMap.has(id), inLocal = localMap.has(id), inRemote = remoteMap.has(id);
    if(inLocal && !inRemote){
      if(inBase) return; // 상대방이 그 사이 삭제함 -> 삭제를 존중
      result.push(localMap.get(id)); // 내가 새로 등록한 항목 -> 보존
      return;
    }
    if(!inLocal && inRemote){
      if(inBase) return; // 내가 그 사이 삭제함 -> 삭제를 존중
      result.push(remoteMap.get(id)); // 상대가 새로 등록한 항목 -> 보존
      return;
    }
    // 양쪽 다 있음 - 기준점 대비 어느 쪽이 실제로 바뀌었는지에 따라 값을 선택
    const baseRec = inBase ? baseMap.get(id) : null;
    const baseStr = baseRec ? JSON.stringify(baseRec) : null;
    const localStr = JSON.stringify(localMap.get(id));
    const remoteStr = JSON.stringify(remoteMap.get(id));
    const localChanged = baseStr===null || localStr!==baseStr;
    const remoteChanged = baseStr===null || remoteStr!==baseStr;
    if(localChanged && !remoteChanged) result.push(localMap.get(id));
    else if(!localChanged) result.push(remoteMap.get(id));
    else result.push(remoteMap.get(id)); // 둘 다 바뀐 드문 경우: 먼저 저장된 서버 값을 우선
  });
  return result;
}
function mergeRemoteDB(baseline, local, remote){
  const merged = {};
  const keys = new Set([...Object.keys(remote||{}), ...Object.keys(local||{})]);
  keys.forEach(key=>{
    const localVal = local ? local[key] : undefined;
    const remoteVal = remote ? remote[key] : undefined;
    const baseVal = baseline ? baseline[key] : undefined;
    if(isIdKeyedArray(localVal) || isIdKeyedArray(remoteVal) || isIdKeyedArray(baseVal)){
      merged[key] = mergeIdArray(baseVal, localVal, remoteVal);
      return;
    }
    const localChanged = JSON.stringify(localVal) !== JSON.stringify(baseVal);
    merged[key] = localChanged ? localVal : remoteVal;
  });
  return merged;
}

async function loadDB(){
  if(sbClient){
    try{
      const { data, error } = await sbClient.from('kpi_db').select('data,version').eq('id',1).single();
      if(error) throw error;
      if(data && data.data && Object.keys(data.data).length > 0){
        DB = data.data;
        DB_VERSION = data.version || 0;
        migrateDB();
        DB_BASELINE = cloneDBSnapshot(DB);
        cacheDBLocally();
        dbReady = true;
        return;
      }
      // 테이블은 있지만 아직 데이터가 비어있는 최초 상태 -> 시드 데이터로 초기화 후 최초 저장
      DB = buildSeedDataFromReal();
      DB_VERSION = 0;
      dbReady = true;
      DB_BASELINE = cloneDBSnapshot(DB);
      await pushDBToServer();
      cacheDBLocally();
      return;
    }catch(e){
      console.error('Supabase에서 데이터를 불러오지 못했습니다. 로컬 캐시로 대체합니다.', e);
    }
  }
  // Supabase 연결 실패/미설정 시: 마지막으로 저장된 로컬 캐시 사용 (오프라인 대비)
  const raw = localStorage.getItem(STORAGE_KEY);
  if(raw){
    try{ DB = JSON.parse(raw); migrateDB(); dbReady = true; DB_BASELINE = cloneDBSnapshot(DB); return; }catch(e){ /* fall through to reseed */ }
  }
  DB = buildSeedDataFromReal();
  dbReady = true;
  DB_BASELINE = cloneDBSnapshot(DB);
}

// 저장 충돌(다른 사용자가 그 사이 먼저 저장함)이 실제로 병합을 유발했을 때 관리자가
// 나중에 확인할 수 있도록 가벼운 로그를 남긴다 - kpi_db 저장 자체와는 분리된 activity_log
// 테이블에 kind='conflict'로 기록하며, 실패해도 저장 흐름에는 영향을 주지 않는다.
function logSaveConflict(mergedDB, beforeDB){
  const changedKeys = Object.keys(mergedDB||{}).filter(k=> JSON.stringify(mergedDB[k]) !== JSON.stringify(beforeDB ? beforeDB[k] : undefined));
  logActivity('conflict', `저장 충돌 병합: ${changedKeys.join(', ') || '(변경 없음)'}`);
}
// 관리자가 [시스템관리]에서 최근 저장 충돌 이력을 확인할 수 있도록 조회한다.
async function fetchRecentConflicts(limit){
  if(!sbClient) return [];
  try{
    const { data, error } = await sbClient.from('activity_log').select('*').eq('kind','conflict').order('created_at',{ascending:false}).limit(limit||10);
    if(error) throw error;
    return data || [];
  }catch(e){ return []; }
}
async function refreshConflictLog(){
  const el = document.getElementById('conflictLogList');
  if(!el) return;
  const items = await fetchRecentConflicts(10);
  el.innerHTML = conflictLogHtml(items);
}
// 시스템 관리 - "저장 충돌 이력" 카드는 평소엔 거의 볼 일이 없어 접어 두고, 필요할 때만
// 펼쳐보게 한다. 데이터는(반응 없어 보이지 않도록) 접혀 있어도 계속 백그라운드로 불러와 두고,
// 이 토글은 순수하게 화면 표시 여부만 바꾼다(다시 그리지 않음).
function toggleConflictLogVisible(){
  const wrap = document.getElementById('conflictLogWrap');
  const btn = document.getElementById('conflictLogToggleBtn');
  if(!wrap || !btn) return;
  const opening = wrap.style.display === 'none';
  wrap.style.display = opening ? '' : 'none';
  btn.textContent = opening ? '접기 ▴' : '펼쳐보기 ▾';
}
function conflictLogHtml(items){
  if(!items || items.length===0) return '최근 저장 충돌 병합 기록이 없습니다.';
  return items.map(it=>{
    const time = (it.created_at||'').slice(0,16).replace('T',' ');
    return `<div style="padding:5px 0;border-bottom:1px solid var(--border);">
      <span class="badge warn" style="margin-right:6px;">병합</span>
      ${escapeHtml(it.name||it.emp_id||'')} · ${time}
      <div class="muted" style="font-size:11.5px;margin-top:2px;">${escapeHtml(it.message||'')}</div>
    </div>`;
  }).join('');
}

// 여러 매니저가 거의 동시에 저장하면(예: 게시글 등록) 버전이 어긋나는 경우가 잦다.
// 버전이 어긋나면 서버의 최신 전체 데이터를 받아와 mergeRemoteDB()로 항목 단위 병합한 뒤
// (내가 새로 등록한 것 + 상대가 새로 등록한 것 모두 보존) 다시 저장을 시도한다.
// 반환값: 실제로 서버에 반영됐으면 true, 아니면 false(호출부에서 저장 완료 토스트 여부 판단에 사용).
async function pushDBToServer(retryCount){
  retryCount = retryCount || 0;
  if(!sbClient){ cacheDBLocally(); return true; }
  const expectedVersion = DB_VERSION;
  const newVersion = expectedVersion + 1;
  try{
    const { data, error } = await sbClient
      .from('kpi_db')
      .update({ data: DB, version: newVersion, updated_at: new Date().toISOString() })
      .eq('id', 1)
      .eq('version', expectedVersion)
      .select('version');
    if(error) throw error;
    if(!data || data.length === 0){
      // 버전 불일치 = 다른 사용자가 그 사이 먼저 저장함.
      if(retryCount < 5){
        try{
          const { data: latest, error: verErr } = await sbClient.from('kpi_db').select('data,version').eq('id',1).single();
          if(!verErr && latest){
            const before = DB;
            const merged = mergeRemoteDB(DB_BASELINE, DB, latest.data);
            if(JSON.stringify(merged) !== JSON.stringify(latest.data)) logSaveConflict(merged, latest.data);
            DB = merged;
            DB_VERSION = latest.version;
            DB_BASELINE = cloneDBSnapshot(latest.data);
            return await pushDBToServer(retryCount + 1);
          }
        }catch(e2){ /* 최신 데이터 확인 자체가 실패하면 아래 최종 안내로 넘어감 */ }
      }
      // 여러 번 재시도해도 계속 충돌하면(매우 드묾) 그제서야 최신 데이터와 병합 후 안내한다.
      return await handleSaveConflict();
    }
    DB_VERSION = newVersion;
    DB_BASELINE = cloneDBSnapshot(DB);
    cacheDBLocally();
    return true;
  }catch(e){
    console.error('DB 저장 실패:', e);
    alert('저장 중 오류가 발생했습니다. 인터넷 연결을 확인한 뒤 다시 시도해 주세요.');
    return false;
  }
}

async function handleSaveConflict(){
  try{
    const { data, error } = await sbClient.from('kpi_db').select('data,version').eq('id',1).single();
    if(error) throw error;
    // 여기서도 무조건 서버 값으로 통째로 덮어쓰지 않고, 가능한 한 방금 입력한 내용을 병합해 살린다.
    const merged = mergeRemoteDB(DB_BASELINE, DB, data.data);
    if(JSON.stringify(merged) !== JSON.stringify(data.data)) logSaveConflict(merged, data.data);
    DB = merged;
    const mergedVersion = data.version || 0;
    DB_VERSION = mergedVersion;
    DB_BASELINE = cloneDBSnapshot(DB);
    cacheDBLocally();
    if(SESSION) renderTab(state.tab);
    // 병합한 결과를 실제로 서버에 한 번 더 저장 시도한다 - 여기까지 왔다는 건 이미 여러 번
    // 재시도했다는 뜻이라, 이 마지막 시도가 성공하면 조용히 끝나고 실패할 때만 안내한다.
    try{
      const { data: upd, error: updErr } = await sbClient
        .from('kpi_db')
        .update({ data: DB, version: mergedVersion + 1, updated_at: new Date().toISOString() })
        .eq('id', 1)
        .eq('version', mergedVersion)
        .select('version');
      if(!updErr && upd && upd.length > 0){
        DB_VERSION = mergedVersion + 1;
        DB_BASELINE = cloneDBSnapshot(DB);
        cacheDBLocally();
        return true;
      }
    }catch(e3){ /* 아래 최종 안내로 진행 */ }
    alert('다른 사용자와 저장이 겹쳐 최신 데이터와 병합했습니다. 방금 입력/변경하신 내용이 잘 반영됐는지 확인해 주세요.');
    return false;
  }catch(e){
    console.error('충돌 처리 중 데이터 갱신 실패:', e);
    return false;
  }
}

function startDbPolling(){
  stopDbPolling();
  dbPollTimer = setInterval(()=>{ pollDbForRemoteChanges(); checkForNewActivityNotifications(); }, 20000);
}
function stopDbPolling(){
  if(dbPollTimer){ clearInterval(dbPollTimer); dbPollTimer = null; }
}
async function pollDbForRemoteChanges(){
  if(!sbClient || !SESSION) return;
  try{
    const { data, error } = await sbClient.from('kpi_db').select('version').eq('id',1).single();
    if(error) throw error;
    if(data && data.version > DB_VERSION){
      const { data: full, error: err2 } = await sbClient.from('kpi_db').select('data,version').eq('id',1).single();
      if(err2) throw err2;
      // 폴링 시점에 화면에 아직 저장 전인 로컬 변경이 남아있을 수 있으므로(예: 여러 장 사진
      // 업로드 처리 중) 통째로 덮어쓰지 않고 저장 충돌 때와 동일하게 항목 단위로 병합한다.
      DB = mergeRemoteDB(DB_BASELINE, DB, full.data);
      DB_VERSION = full.version;
      DB_BASELINE = cloneDBSnapshot(full.data);
      cacheDBLocally();
      const activeTag = (typeof document!=='undefined' && document.activeElement) ? document.activeElement.tagName : '';
      if(activeTag !== 'INPUT' && activeTag !== 'TEXTAREA' && activeTag !== 'SELECT'){
        renderTab(state.tab);
      }
    }
  }catch(e){ console.error('원격 변경사항 확인 실패:', e); }
}

/* =========================================================================
   1a3. 접속 현황 / 알림 (activity_log 테이블 — presence + 알림 + 로그인 기록)
   heartbeat(접속 유지 신호) / login(로그인 기록) / post(게시글 등록 알림) /
   update(관리자 자료 갱신 알림) 4가지 kind를 하나의 activity_log 테이블에
   기록한다. kpi_db 본체와 완전히 분리된 별도 테이블이라, 잦은 접속 신호를
   보내도 kpi_db 저장 시 발생하는 "다른 사용자가 먼저 저장했습니다" 버전
   충돌 알림과는 무관하게 동작한다.
   ========================================================================= */
let heartbeatTimer = null;
function startHeartbeat(){
  stopHeartbeat();
  sendHeartbeat();
  heartbeatTimer = setInterval(sendHeartbeat, 60000);
}
function stopHeartbeat(){
  if(heartbeatTimer){ clearInterval(heartbeatTimer); heartbeatTimer = null; }
}
async function sendHeartbeat(){
  if(!sbClient || !SESSION) return;
  try{
    await sbClient.from('activity_log').insert({ emp_id: SESSION.empId, name: SESSION.name, kind: 'heartbeat' });
    const cutoff = new Date(Date.now() - 10*60*1000).toISOString();
    await sbClient.from('activity_log').delete().eq('kind','heartbeat').lt('created_at', cutoff);
  }catch(e){ /* 접속 신호 실패는 조용히 무시 (핵심 기능 아님) */ }
}
async function fetchOnlineCount(){
  if(!sbClient) return null;
  try{
    const cutoff = new Date(Date.now() - 2*60*1000).toISOString();
    const { data, error } = await sbClient.from('activity_log').select('emp_id').eq('kind','heartbeat').gt('created_at', cutoff);
    if(error) throw error;
    return new Set((data||[]).map(r=>r.emp_id)).size;
  }catch(e){ return null; }
}
async function logActivity(kind, message){
  if(!sbClient || !SESSION) return;
  try{
    await sbClient.from('activity_log').insert({ emp_id: SESSION.empId, name: SESSION.name, kind, message: message || null });
  }catch(e){ /* 알림 기록 실패는 조용히 무시 (핵심 기능 아님) */ }
}
async function fetchRecentActivity(limit){
  if(!sbClient) return [];
  try{
    const { data, error } = await sbClient.from('activity_log').select('*').in('kind',['post','update']).order('created_at',{ascending:false}).limit(limit||20);
    if(error) throw error;
    return data || [];
  }catch(e){ return []; }
}
let loginStatsCache = null;
async function fetchLoginStats(){
  if(!sbClient) return {};
  try{
    const { data, error } = await sbClient.from('activity_log').select('emp_id,created_at').eq('kind','login').order('created_at',{ascending:false}).limit(5000);
    if(error) throw error;
    const stats = {};
    (data||[]).forEach(r=>{
      if(!stats[r.emp_id]) stats[r.emp_id] = { count:0, last:null };
      stats[r.emp_id].count++;
      if(!stats[r.emp_id].last || r.created_at > stats[r.emp_id].last) stats[r.emp_id].last = r.created_at;
    });
    return stats;
  }catch(e){ return {}; }
}
function loadLoginStatsIfNeeded(){
  if(loginStatsCache || !sbClient) return;
  fetchLoginStats().then(stats=>{
    loginStatsCache = stats;
    if(SESSION && state.tab==='accountManagement') renderTab('accountManagement');
  });
}

// "주말 정책 숙지도 점검" 마감일 버그(§POLICY_QUIZ_CURRENT_WEEK_DEADLINE 옆 주석 참고) 1회 보정.
// 이미 저장된 DB에 옛날의 잘못된 마감일(8/8, 토요일까지만)이 그대로 남아있으면 "주말"(토+일)
// 취지에 맞는 8/9(일요일)로 자동 교정한다. 관리자가 이미 다른 값으로 바꿔놨다면(=저장된 값이
// 옛날 잘못된 값과 다르면) 건드리지 않는다. migrateDB()에서 호출되지만, 의존성이 적어 별도
// 함수로 분리해 독립적으로 테스트할 수 있게 했다.
function applyPolicyQuizDeadlineFix(){
  if(DB.policyQuizDeadlineFixVersion === POLICY_QUIZ_DEADLINE_FIX_VERSION) return;
  const wkMeta = DB.policyQuizWeekMeta && DB.policyQuizWeekMeta[POLICY_QUIZ_CURRENT_WEEK_KEY];
  if(wkMeta && wkMeta.deadline === '2026-08-08'){
    wkMeta.deadline = '2026-08-09';
  }
  DB.policyQuizDeadlineFixVersion = POLICY_QUIZ_DEADLINE_FIX_VERSION;
}
function migrateDB(){
  // fills in fields for DBs saved before a feature was added.
  // (여러 사용자가 거의 동시에 로그인할 때마다 실제 변경사항이 없는데도
  // 매번 서버에 재저장하면 불필요한 버전 충돌이 발생하므로, 실제로
  // 무언가 채워 넣은 경우에만 saveDB()를 호출한다.)
  const __migrateBefore = JSON.stringify(DB);
  // 지점명 앞에 붙어있던 "(신)이마트 " 접두어를 정리한다. 관리 대상 지점이 전부 "(신)이마트"라서
  // 구분에 아무 의미가 없고, 취합방 지점 선택 pill/드롭다운 등에서 이름만 불필요하게 길어 보였다.
  // DB.branches[].name 자체를 1회성으로 정리해두면 branchName()/branchOptionsHtml()/지점 pill 등
  // 지점명을 표시하는 모든 화면에 한 번에 일관되게 반영된다.
  (DB.branches||[]).forEach(b=>{
    if(b && b.name){
      const stripped = b.name.replace(/^\(신\)\s*이마트\s*/, '').trim();
      if(stripped) b.name = stripped;
    }
  });
  if(!DB.schedule) DB.schedule = {};
  if(!DB.competitiveness) DB.competitiveness = {};
  if(!DB.competitivenessSummary) DB.competitivenessSummary = null;
  if(!DB.competitivenessHistory) DB.competitivenessHistory = {};
  if(!DB.subscriptionData) DB.subscriptionData = {};
  if(!DB.subscriptionData[currentGoalsPeriod()] && Object.keys(DB.subscriptionData).length===0){
    DB.subscriptionData[currentGoalsPeriod()] = JSON.parse(JSON.stringify(SUBSCRIPTION_DATA));
  }
  if(!DB.inventory) DB.inventory = [];
  DB.inventory.forEach(r=>{
    if(r.amountWon===undefined) r.amountWon = null;
    if(r.saleStatus===undefined) r.saleStatus = '판매가능';
    if(r.note===undefined) r.note = '';
    if(r.status===undefined) r.status = '보유중';
    if(r.displayDate===undefined) r.displayDate = '';
    if(r.displaySoldOutDate===undefined) r.displaySoldOutDate = '';
  });
  if(!DB.notices) DB.notices = [];
  DB.notices.forEach(n=>{ if(!n.attachments) n.attachments = []; });
  if(!DB.noticeReads) DB.noticeReads = {};
  if(!DB.materials) DB.materials = [];
  DB.materials.forEach(n=>{ if(!n.attachments) n.attachments = []; });
  if(!DB.materialReads) DB.materialReads = {};
  if(!DB.infoReports) DB.infoReports = [];
  DB.infoReports.forEach(r=>{ if(!r.attachments) r.attachments = []; });
  if(!DB.execPhotos) DB.execPhotos = [];
  if(!DB.giftcardRequests) DB.giftcardRequests = [];
  if(DB.giftcardBudgetWon===undefined || DB.giftcardBudgetWon===null) DB.giftcardBudgetWon = 0;
  if(!DB.mistakeNotes) DB.mistakeNotes = [];
  if(!DB.bestPractices) DB.bestPractices = [];
  if(!DB.issueCases) DB.issueCases = [];
  if(!DB.suggestions) DB.suggestions = [];
  if(!DB.contestGifts) DB.contestGifts = [];
  // 로니 런칭 기념 사은품 한정수량이 12건→24건으로 늘어나며 문구도 함께 바뀌었으므로,
  // 기존에 "(12건 선착순 한정)" 문구로 등록돼 있던 건들도 새 문구 기준으로 계속 집계·표시되도록
  // contestType 값을 새 문구로 맞춰준다(기존 등록건을 24건 집계에 포함시키기 위함).
  DB.contestGifts.forEach(r=>{
    if(r.contestType==='26년 8월 로니 런칭 기념 사은품(12건 선착순 한정)'){
      r.contestType = '26년 8월 로니 런칭 기념 사은품(24건 선착순 한정)';
    }
  });
  if(!DB.subTierContestGifts) DB.subTierContestGifts = [];
  // 근무일정(Shiftee) 업로드 데이터: 사번+날짜로 조회하는 평면 구조. 지점별로 파일을 나눠 올려도
  // 사번 단위로 병합되므로 여러 지점 파일을 순서에 상관없이 추가해도 서로 덮어쓰지 않는다.
  if(!DB.workSchedule) DB.workSchedule = { byEmpDate:{}, uploads:[] };
  if(!DB.workSchedule.byEmpDate) DB.workSchedule.byEmpDate = {};
  if(!DB.workSchedule.uploads) DB.workSchedule.uploads = [];
  // "지표 한 눈에 보기" 업로드 데이터(대형마트채널 지점Master 시트 스냅샷). 매번 올릴 때마다
  // 통째로 최신 스냅샷으로 교체된다(과거 값을 누적 보관하지 않음 — 필요해지면 이후 이력화 가능).
  if(!DB.metricsOverview) DB.metricsOverview = { asOfDate:null, rows:[], uploadedAt:null, uploadedBy:null, fileName:null };
  // 2026-08-25 추가: "구독 판매 Grade 및 현장관리자 시상 컨테스트" 파일의 "지점별 구독 판매" 시트를
  // 별도로 올려 [구독 실적] 페이지의 총판/실판/전년마감 데이터를 더 정확하고 자주 갱신할 수 있게
  // 한다(목표는 계속 [지표 한 눈에 보기] 업로드분의 s_target을 사용). byKey는 지점명을
  // metricsOverviewNormName으로 정규화한 키.
  if(!DB.subSalesUpload) DB.subSalesUpload = { asOfDate:null, byKey:{}, uploadedAt:null, uploadedBy:null, fileName:null };
  // 같은 파일의 "1. 매니저 구독 Grade" 시트: 매니저(직원) 개인별 구독 Grade 시상금 명단.
  // branchKey는 metricsOverviewNormName 정규화 키, records는 그 지점 소속 직원별 배열.
  if(!DB.subGradeIncentive) DB.subGradeIncentive = { asOfDate:null, byBranchKey:{}, uploadedAt:null, uploadedBy:null, fileName:null };
  // 장기 미사용 시 자동 전환되는 스크린세이버 사용 여부 (관리자가 시스템 관리에서 설정, 기본값 사용함)
  if(DB.screensaverEnabled===undefined || DB.screensaverEnabled===null) DB.screensaverEnabled = true;
  // 모바일 상품권 취합 등록 일시 정지 여부 (관리자가 필요 시 켜고 끔, 기본값은 등록 가능)
  if(DB.giftcardRegistrationLocked===undefined || DB.giftcardRegistrationLocked===null) DB.giftcardRegistrationLocked = false;
  if(!DB.eduSchedules) DB.eduSchedules = { hq: [], inhouse: [], etc: [] };
  if(!DB.eduSchedules.hq) DB.eduSchedules.hq = [];
  if(!DB.eduSchedules.inhouse) DB.eduSchedules.inhouse = [];
  if(!DB.eduSchedules.etc) DB.eduSchedules.etc = [];
  ['hq','inhouse','etc'].forEach(cat=>{
    DB.eduSchedules[cat].forEach(s=>{
      if(s.targetEmpIds===undefined) s.targetEmpIds = [];
      if(s.alarmDaysBefore===undefined) s.alarmDaysBefore = null;
      // 몇박 며칠짜리 교육(숙박 교육 등) 지원 - 종료일이 없으면 시작일과 같은 하루짜리 일정으로 취급.
      if(s.endDate===undefined) s.endDate = null;
    });
  });
  if(!DB.eduCompletion) DB.eduCompletion = { video: [], test: [], aiRp: [] };
  if(!DB.eduCompletion.video) DB.eduCompletion.video = [];
  if(!DB.eduCompletion.test) DB.eduCompletion.test = [];
  if(!DB.eduCompletion.aiRp) DB.eduCompletion.aiRp = [];
  // 화상교육 이수율은 이제 "기준날짜/회차별 교육명"이 포함된 신규 서식 파일로 업로드하며,
  // 업로드 시 이 필드에 회차별 상세 데이터가 저장된다(구서식 DB.eduCompletion.video는 리마인더용으로 함께 동기화됨).
  if(DB.eduVideoRich===undefined) DB.eduVideoRich = null;
  // 재고 조회: "소진리스트" 시트에서 추출한 소진집중 대상 상품코드 목록(깜빡이는 알림 배지용)
  if(!DB.inventoryClearanceCodes) DB.inventoryClearanceCodes = [];
  if(DB.inventoryClearanceBaseline===undefined) DB.inventoryClearanceBaseline = null;
  // 여러 영업팀 재고가 섞인 파일을 올려도 기본은 혼매경북팀만 표시 - 관리자가 켜면 전체 팀 표시
  if(DB.inventoryShowAllTeams===undefined) DB.inventoryShowAllTeams = false;
  if(!DB.kakaoFriends) DB.kakaoFriends = [];
  DB.kakaoFriends.forEach(r=>{ if(!r.date) r.date = r.weekStart; if(!r.weekStart && r.date) r.weekStart = getMondayStr(r.date); });
  if(!DB.prospects) DB.prospects = [];
  DB.prospects.forEach(p=>{ if(p.purchaseType===undefined) p.purchaseType = null; });
  // 2026-08-24 방문 상담 일지 양식에 맞춰 방문일자/방문시간/고객구분/방문단위/방문경로/상담제품
  // 대분류 6개 항목을 추가했다. 그 이전에 등록된 건들은 값이 없으니 전부 null로 채워 넣는다.
  (DB.prospects||[]).forEach(p=>{
    if(p.visitDate===undefined) p.visitDate = null;
    if(p.visitTime===undefined) p.visitTime = null;
    if(p.customerAgeGroup===undefined) p.customerAgeGroup = null;
    if(p.visitUnit===undefined) p.visitUnit = null;
    if(p.visitChannel===undefined) p.visitChannel = null;
    if(p.productCategory===undefined) p.productCategory = null;
  });
  if(!DB.subB2bSales) DB.subB2bSales = [];
  if(!DB.policyQuizAttempts) DB.policyQuizAttempts = [];
  if(!DB.kakaoContestInfo) DB.kakaoContestInfo = JSON.parse(JSON.stringify(KAKAO_CONTEST_INFO));
  if(DB.kakaoContestResultImage===undefined) DB.kakaoContestResultImage = null;
  // 컨테스트 결과 이미지도 실행력 점검 사진 가이드와 동일하게 1장(dataUrl 단일 필드) ->
  // 여러 개(images[] 배열) 구조로 바뀌었으므로, 기존 단일 이미지를 배열 첫 항목으로 이전한다.
  if(DB.kakaoContestResultImage && DB.kakaoContestResultImage.dataUrl && !DB.kakaoContestResultImage.images){
    DB.kakaoContestResultImage = {
      images: [{dataUrl: DB.kakaoContestResultImage.dataUrl, name: DB.kakaoContestResultImage.name}],
      uploadedAt: DB.kakaoContestResultImage.uploadedAt, uploadedBy: DB.kakaoContestResultImage.uploadedBy
    };
  }
  if(DB.execPhotoGuide===undefined) DB.execPhotoGuide = null;
  // 실행력 점검 사진 가이드: 예전엔 이미지 1장(dataUrl 단일 필드)만 등록 가능했는데, 여러 장을
  // 한 번에 올릴 수 있도록 images[] 배열 구조로 바꿨다. 기존에 저장돼 있던 단일 이미지는
  // images 배열의 첫 번째 항목으로 옮겨서 그대로 보존한다.
  if(DB.execPhotoGuide && DB.execPhotoGuide.dataUrl && !DB.execPhotoGuide.images){
    DB.execPhotoGuide = {
      week: DB.execPhotoGuide.week,
      images: [{dataUrl: DB.execPhotoGuide.dataUrl, name: DB.execPhotoGuide.name}],
      uploadedAt: DB.execPhotoGuide.uploadedAt, uploadedBy: DB.execPhotoGuide.uploadedBy
    };
  }
  // ---- 취합 페이지 공지배너(문구+사진, 관리자 편집/삭제 가능) ----
  // 신규 페이지(구독연동사은품 취합)는 빈 상태로 시작하고, 기존에 코드에 하드코딩되어 있던
  // 구독4품목↑/금액대별 사은품 취합 · 모바일 상품권 취합 배너는 최초 1회만 기존 문구/이미지를
  // 그대로 시드(seed)하여, 이후로는 관리자가 앱에서 직접 수정·삭제할 수 있게 한다.
  if(!DB.collectionNotices) DB.collectionNotices = {};
  if(!DB.collectionNotices.collectContest) DB.collectionNotices.collectContest = { text:'', images:[] };
  if(!DB.collectionNotices.subTierContest) DB.collectionNotices.subTierContest = {
    text: `📢 인터비즈_경북2담당 '26년 8월 Contest
🔥 매니저님들을 위한 8월 특별 혜택! 🔥
이번 달도 파이팅하여 준비된 사은품 모두 챙겨가세요! 🎁
-----------------------------------
✨ Contest. 1 [구독 4품목 계약 시]
👉 앤루시 에어스톰R 리모컨 써큘레이터
✨ Contest. 2 [금액대별 달성 혜택]
👉 800만원 금액대  : [제너] 클로제 IH 스텐냄비 3종 세트
👉 1,000만원 금액대 : [에스트] 세라믹 후라이팬 2종 세트
-----------------------------------
※ 업체 재고에 따른 이슈 발생 시 제품이 변경될 수 있습니다. (이미지는 참고용)
※해당 사은품은 지점으로 배송됩니다`,
    images: [{ dataUrl: SUB_TIER_CONTEST_BANNER_IMG, name:'기존 배너 이미지' }]
  };
  if(!DB.collectionNotices.collectGiftcard) DB.collectionNotices.collectGiftcard = {
    text: '⚠ 반드시 운영안을 숙지하고 사용해주시기 바랍니다 (당월 한도 150만원)',
    images: [
      { dataUrl: MOBILE_GIFTCARD_GUIDE_IMAGES[0], name:"'26년 8월 이마트 모바일 및 사은품 운영 안내" },
      { dataUrl: MOBILE_GIFTCARD_GUIDE_IMAGES[1], name:"'26년 8월 이마트 집중 소진 모델 모바일 지원 안내" }
    ]
  };
  if(!DB.policyQuizBank) DB.policyQuizBank = JSON.parse(JSON.stringify(POLICY_QUIZ_BANK));
  // 문제 은행이 통째로 새 주차 내용으로 교체된 경우(POLICY_QUIZ_BANK_VERSION 상승), 관리자가
  // 개별로 추가/수정한 이력이 없는 "구버전 그대로"인 DB만 최신 은행으로 1회 자동 교체한다.
  if(DB.policyQuizBankVersion !== POLICY_QUIZ_BANK_VERSION){
    DB.policyQuizBank = JSON.parse(JSON.stringify(POLICY_QUIZ_BANK));
    DB.policyQuizBankVersion = POLICY_QUIZ_BANK_VERSION;
  }
  // 정책 숙지도 점검을 "주(week)마다 별도 문제은행 + 표시라벨 + 응시마감일"을 갖는 구조로 1회 이관.
  // 기존 단일 DB.policyQuizBank(있다면)는 POLICY_QUIZ_CURRENT_WEEK_KEY 주의 문제은행으로 그대로
  // 옮겨서, 이미 갱신해둔 이번 주(8월2주차) 20문제가 사라지지 않게 한다.
  if(DB.policyQuizStructureVersion !== POLICY_QUIZ_STRUCTURE_VERSION){
    if(!DB.policyQuizWeeklyBanks) DB.policyQuizWeeklyBanks = {};
    if(!DB.policyQuizWeekMeta) DB.policyQuizWeekMeta = {};
    if(!DB.policyQuizWeeklyBanks[POLICY_QUIZ_CURRENT_WEEK_KEY]){
      DB.policyQuizWeeklyBanks[POLICY_QUIZ_CURRENT_WEEK_KEY] = (DB.policyQuizBank && DB.policyQuizBank.length>0)
        ? DB.policyQuizBank
        : JSON.parse(JSON.stringify(POLICY_QUIZ_BANK));
    }
    if(!DB.policyQuizWeekMeta[POLICY_QUIZ_CURRENT_WEEK_KEY]){
      DB.policyQuizWeekMeta[POLICY_QUIZ_CURRENT_WEEK_KEY] = { label: POLICY_QUIZ_CURRENT_WEEK_LABEL, deadline: POLICY_QUIZ_CURRENT_WEEK_DEADLINE };
    }
    DB.policyQuizStructureVersion = POLICY_QUIZ_STRUCTURE_VERSION;
  }
  applyPolicyQuizDeadlineFix();
  if(!DB.policyQuizWeeklyBanks) DB.policyQuizWeeklyBanks = {};
  if(!DB.policyQuizWeekMeta) DB.policyQuizWeekMeta = {};
  DB.branches.forEach(b=>{
    if(!DB.schedule[b.id]) DB.schedule[b.id] = {};
    if(!DB.goals[b.id]) DB.goals[b.id] = {};
    // 기존 방식(지점당 단일 목표 레코드)에서 월별 관리 방식(기간별 레코드 맵)으로 1회 변환
    if(typeof DB.goals[b.id].target === 'number'){
      const oldFlat = DB.goals[b.id];
      const oldPeriod = oldFlat.period || currentGoalsPeriod();
      DB.goals[b.id] = { [oldPeriod]: oldFlat };
    }
    Object.values(DB.goals[b.id]).forEach(g=>{
      if(g.subQtyTarget===undefined) g.subQtyTarget = 0;
      if(g.subAmtTarget===undefined) g.subAmtTarget = 0;
      if(g.targetIsEstimated===undefined) g.targetIsEstimated = false;
      (g.allocations||[]).forEach(a=>{
        if(a.subQtyTarget===undefined) a.subQtyTarget = 0;
        if(a.subAmtTarget===undefined) a.subAmtTarget = 0;
      });
    });
    if(!DB.progress[b.id]) DB.progress[b.id] = {period: periodStr(), entries:[]};
    if(!DB.attendance[b.id]) DB.attendance[b.id] = {date: todayStr(), records:[]};
  });
  // 실행력 점검 사진: 건당 사진 1장(photoDataUrl)만 가능하던 구조를 여러 장(photos[])으로 바꾼다.
  // 기존에 이미 등록되어 있던 단일 사진은 photos 배열의 첫 번째 항목으로 옮겨서 그대로 보존한다.
  (DB.execPhotos||[]).forEach(r=>{
    if(!r.photos){
      r.photos = r.photoDataUrl ? [{ dataUrl: r.photoDataUrl, name: r.photoName || null }] : [];
    }
    delete r.photoDataUrl;
    delete r.photoName;
  });
  // 모바일 상품권 영수증: 건당 영수증 1장(receiptDataUrl)만 가능하던 구조를 여러 장(receipts[])으로 바꾼다.
  (DB.giftcardRequests||[]).forEach(r=>{
    if(!r.receipts){
      r.receipts = r.receiptDataUrl ? [{ dataUrl: r.receiptDataUrl, name: r.receiptName || null }] : [];
    }
    delete r.receiptDataUrl;
    delete r.receiptName;
  });
  // '매니저'(manager)/'사원'(staff) 두 직책으로 나뉘어 있던 것을 '매니저' 하나로 통일한다
  // (권한 로직은 이미 staff 기준 체크가 대부분이었으므로, manager로 등록돼 있던 계정만
  // staff로 이관하면 직책 표시도 자연히 "매니저"로 통일된다).
  (DB.users||[]).forEach(u=>{ if(u.role==='manager') u.role = 'staff'; });
  // 재고 조회 데이터에 id가 없던 옛 행들(재고 파일을 처음 올렸을 때는 신규 상품에 id를
  // 부여하지 않았음)에 1회성으로 id를 채워 넣는다. id가 없는 행이 하나라도 섞여 있으면
  // mergeRemoteDB가 이 목록 전체를 "id로 식별되지 않는 목록"으로 취급해 통째로 덮어쓰는
  // 방식으로 병합해버려서, 다른 사람이 옛 데이터를 들고 있다가 아무 항목이나 하나 수정해
  // 저장하기만 해도 방금 새로 올린 전체 재고 데이터가 사라질 수 있었다(2026.08 확인된 사고).
  (DB.inventory||[]).forEach((r,idx)=>{
    if(r.id==null) r.id = 'inv_' + Date.now() + '_' + idx + '_' + Math.random().toString(36).slice(2,6);
  });
  if(JSON.stringify(DB) !== __migrateBefore) saveDB(true);
}
// silent=true면 저장은 그대로 하되 "저장되었습니다" 토스트를 띄우지 않는다 - 사용자가 직접
// 누른 등록/수정/삭제가 아니라 백그라운드 마이그레이션, 공지 읽음 처리, 마지막 조회 시각
// 기록처럼 사용자 눈에 "내가 뭔가 저장했다"고 느껴지면 안 되는 자동 저장에 사용한다.
function saveDB(silent){
  // 임원(조회 전용) 계정은 어떤 경로로 saveDB()가 호출되더라도 서버에 절대 반영되지 않는다 —
  // 등록/수정/삭제 버튼을 개별적으로 다 찾아 막는 것보다 이 한 곳을 막는 게 가장 확실하다.
  if(SESSION && SESSION.role==='exec') return;
  const p = pushDBToServer();
  if(!silent){
    p.then(ok=>{ if(ok) showSaveBanner('저장되었습니다.'); }).catch(()=>{});
  }
}
// "저장되었습니다" 확인은 화면 우측 구석의 작은 토스트로는 잘 안 보인다는 의견이 있어,
// 등록/수정/삭제할 때마다 뜨는 이 저장 확인만은 화면 중앙 상단에 크게 표시하고 확인 버튼
// 없이 잠깐 후 자동으로 사라지게 한다(업로드 결과 등 다른 안내는 기존 showToast를 그대로 쓴다).
function showSaveBanner(message){
  let container = document.getElementById('saveBannerContainer');
  if(!container){
    container = document.createElement('div');
    container.id = 'saveBannerContainer';
    container.className = 'save-banner-container';
    document.body.appendChild(container);
  }
  container.querySelectorAll('.save-banner').forEach(el=> el.remove()); // 연속 저장 시 이전 배너가 겹치지 않게 정리
  const banner = document.createElement('div');
  banner.className = 'save-banner';
  banner.innerHTML = `<span class="sb-icon">✅</span><span>${message}</span>`;
  container.appendChild(banner);
  setTimeout(()=>{
    banner.classList.add('sb-out');
    setTimeout(()=> banner.remove(), 250);
  }, 1800);
}

/* =========================================================================
   1b. AUTO-PROVISION FROM UPLOADED FILE (one file, all branches/managers)
   ========================================================================= */
function slugify(s){
  const cleaned = String(s).trim().replace(/[^a-zA-Z0-9가-힣]/g,'');
  return cleaned ? cleaned.slice(0,16) : ('id'+Math.random().toString(36).slice(2,8));
}
// creates the branch (with empty goals/progress/attendance/schedule) if it doesn't exist yet
function ensureBranch(name){
  name = String(name).trim();
  let b = DB.branches.find(x=>x.name===name);
  if(!b){
    const id = 'br_' + slugify(name) + '_' + Math.random().toString(36).slice(2,5);
    b = {id, name};
    DB.branches.push(b);
    DB.goals[id] = { [currentGoalsPeriod()]: {period: currentGoalsPeriod(), target:0, allocations:[], subQtyTarget:0, subAmtTarget:0, targetIsEstimated:true} };
    DB.progress[id] = {period: periodStr(), entries:[]};
    DB.attendance[id] = {date: todayStr(), records:[]};
    DB.schedule[id] = {};
  }
  return b;
}
// creates a staff account (pw 1234) for a name found in the uploaded file if not already known,
// and makes sure that branch's goal-allocation / attendance tables have a row for them
function ensureUser(empIdRaw, name, branchId){
  name = String(name).trim();
  let u = DB.users.find(x=>x.name===name && x.branchId===branchId);
  let created = false;
  if(!u){
    const empId = (empIdRaw && String(empIdRaw).trim()) || ('auto' + slugify(name) + slugify(branchId));
    u = DB.users.find(x=>x.empId===empId);
    if(!u){
      u = {empId, pw:'1234', name, role:'staff', branchId};
      DB.users.push(u);
      created = true;
    }
  }
  const g = getGoals(branchId, currentGoalsPeriod());
  if(g && !g.allocations.find(a=>a.empId===u.empId)){
    g.allocations.push({empId:u.empId, name:u.name, target:0, subQtyTarget:0, subAmtTarget:0});
  }
  const att = DB.attendance[branchId];
  if(att && !att.records.find(r=>r.empId===u.empId)){
    att.records.push({empId:u.empId, name:u.name, status:'출근', checkin:'09:00', checkout:'18:00'});
  }
  return {user:u, created};
}

/* =========================================================================
   2. SESSION / AUTH
   ========================================================================= */
let SESSION = null; // {empId, name, role, branchId}
const REMEMBER_ID_KEY = 'lg_kpi_remember_id';
const SESSION_STORAGE_KEY = 'lg_kpi_session';
// 새로고침해도 홈 대시보드로 돌아가지 않고 마지막으로 보던 화면이 그대로 뜨도록, 탭을
// 전환할 때마다(renderTab) 마지막 탭 키를 여기에 저장해 둔다.
const LAST_TAB_STORAGE_KEY = 'lg_kpi_last_tab';
// renderTab()이 실제로 처리하는 탭 키 전체 목록 - 새로고침 복원 시 저장된 값이 이 중 하나가
// 아니면(예: 옛 버전에서 남은 값, 조작된 값) 안전하게 홈으로 대체한다.
const VALID_TABS = ['home','systemAdmin','accountManagement','metricsOverview','goals','notices','materials',
  'infoReports','subscription','subB2bSales','sales','incentiveOverview','inventory','collectPhoto','collectGiftcard','collectContest',
  'subTierContest','mistakeNote','issueCase','bestPractice','policyQuiz','eduHq','eduInhouse','eduEtc','eduVideo',
  'eduTest','eduAiRp','kakaoFriends','prospects','suggestions'];

/* =========================================================================
   2b. 개인화 UI 설정 (다크모드/글자크기/밀도/홈 위젯 켜고끄기+순서/즐겨찾기 메뉴/
   최근 검색어/저장된 필터) - 계정(empId)별로 이 브라우저에만 저장된다.
   서버(DB)에는 올라가지 않는 순수 화면 설정이라 다른 사람과 공유되지 않고, 다른 PC로
   로그인하면 그 PC의 기본값부터 다시 시작한다.
   ========================================================================= */
function uiPrefsStorageKey(){
  return 'lg_kpi_uiprefs_' + (SESSION && SESSION.empId ? SESSION.empId : 'anon');
}
function defaultUiPrefs(){
  return {
    darkMode: false,
    fontSize: 'normal',       // 'small' | 'normal' | 'large'
    density: 'comfortable',   // 'comfortable' | 'compact'
    hiddenHomeWidgets: [],    // HOME_WIDGETS 중 숨긴 위젯 key 목록
    homeWidgetOrder: [],      // HOME_WIDGETS key 순서(비어있으면 기본 순서)
    pinnedNav: [],            // 즐겨찾기로 고정한 탭 key 목록
    recentSearches: [],       // 최근 검색어(최신순)
    savedFilters: {}          // { pageKey: [{name, filter, savedAt}] }
  };
}
function loadUiPrefs(){
  let saved = null;
  try{ saved = JSON.parse(localStorage.getItem(uiPrefsStorageKey()) || 'null'); }catch(e){ saved = null; }
  state.uiPrefs = Object.assign(defaultUiPrefs(), saved || {});
  applyUiPrefsToDocument();
}
function saveUiPrefs(){
  if(!state.uiPrefs) return;
  try{ localStorage.setItem(uiPrefsStorageKey(), JSON.stringify(state.uiPrefs)); }catch(e){ /* 저장 공간 문제 등은 무시 */ }
}
function applyUiPrefsToDocument(){
  const p = state.uiPrefs || defaultUiPrefs();
  document.body.classList.toggle('dark-mode', !!p.darkMode);
  document.body.classList.remove('font-small', 'font-large');
  if(p.fontSize==='small') document.body.classList.add('font-small');
  if(p.fontSize==='large') document.body.classList.add('font-large');
  document.body.classList.toggle('density-compact', p.density==='compact');
}
function resetUiPrefsOnLogout(){
  // 로그아웃 시 화면 상태(다크모드 등)를 기본값으로 되돌린다 - 같은 PC에서 다른 계정으로
  // 로그인할 때 이전 사람 설정이 잠깐이라도 남아 보이지 않도록.
  state.uiPrefs = null;
  document.body.classList.remove('dark-mode', 'font-small', 'font-large', 'density-compact');
}

// 아이디 저장 체크박스: 로그인 화면이 뜰 때(최초 로드/로그아웃 후) 저장된 아이디가 있으면
// 입력창에 미리 채워주고 체크박스도 켜둔다.
function applyRememberedLoginId(){
  const idEl = document.getElementById('loginId');
  const checkEl = document.getElementById('loginRememberId');
  if(!idEl || !checkEl) return;
  let remembered = '';
  try{ remembered = localStorage.getItem(REMEMBER_ID_KEY) || ''; }catch(e){ /* 무시 */ }
  if(remembered){ idEl.value = remembered; checkEl.checked = true; }
  else { checkEl.checked = false; }
}

// 로그인 성공 후 화면 전환/사이드바 갱신/폴링 시작 등 공통 처리.
// fromRestore가 true면 새로고침 등으로 저장된 세션을 복원한 경우이므로 로그인 활동 로그는 남기지 않는다.
function enterApp(user, fromRestore){
  SESSION = {empId:user.empId, name:user.name, role:user.role, branchId:user.branchId};
  document.getElementById('loginScreen').style.display='none';
  document.getElementById('app').classList.add('active');
  document.getElementById('sbUserName').textContent = user.name + (user.role==='admin'?' (관리자)':(user.role==='exec'?' (임원)':''));
  document.getElementById('sbUserMeta').textContent = user.role==='admin' ? '본사' : (user.role==='exec' ? '임원 (전 지점 조회)' : (branchName(user.branchId) + ' · 매니저'));
  updateNavVisibilityForRole();
  state.viewBranchId = user.branchId || DB.branches[0].id;
  state.eduReminders = computeEduReminders();
  loadUiPrefs();
  renderNavPins();
  // 새로고침으로 세션을 복원하는 경우(fromRestore)에만 마지막으로 보던 탭을 그대로 이어서
  // 보여준다 - 아이디/비밀번호로 새로 로그인할 때는 지금처럼 항상 홈에서 시작한다.
  let initialTab = 'home';
  if(fromRestore){
    let savedTab = null;
    try{ savedTab = localStorage.getItem(LAST_TAB_STORAGE_KEY); }catch(e){ /* 무시 */ }
    if(savedTab && VALID_TABS.includes(savedTab)) initialTab = savedTab;
  }
  renderTab(initialTab);
  startDbPolling();
  startHeartbeat();
  startScreensaverWatch();
  if(!fromRestore) logActivity('login');
}
function handleLogin(){
  const err = document.getElementById('loginError');
  if(!dbReady){ err.textContent='데이터를 아직 불러오는 중입니다. 잠시 후 다시 시도해 주세요.'; return; }
  const id = document.getElementById('loginId').value.trim();
  const pw = document.getElementById('loginPw').value.trim();
  const user = DB.users.find(u=>u.empId===id && u.pw===pw);
  if(!user){ err.textContent='사번 또는 비밀번호가 올바르지 않습니다.'; return; }
  err.textContent='';
  // 아이디 저장 체크 여부에 따라 다음 접속 시 자동으로 채워지도록 저장/삭제한다.
  const rememberChecked = !!(document.getElementById('loginRememberId') && document.getElementById('loginRememberId').checked);
  try{
    if(rememberChecked) localStorage.setItem(REMEMBER_ID_KEY, id);
    else localStorage.removeItem(REMEMBER_ID_KEY);
  }catch(e){ /* 저장 공간 문제 등은 무시 */ }
  // 새로고침해도 로그인 상태가 유지되도록 세션을 저장해 둔다.
  try{ localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify({empId:user.empId})); }catch(e){ /* 무시 */ }
  enterApp(user, false);
}
// 페이지가 새로고침되어도 로그아웃되지 않도록, 저장된 세션이 있으면 자동으로 복원한다.
// (계정이 그 사이 삭제되었을 수 있으니 DB.users에서 다시 조회해서 유효할 때만 복원한다)
function restoreSessionIfAny(){
  let saved = null;
  try{ saved = JSON.parse(localStorage.getItem(SESSION_STORAGE_KEY) || 'null'); }catch(e){ saved = null; }
  if(!saved || !saved.empId) return false;
  const user = DB.users.find(u=>u.empId===saved.empId);
  if(!user){ try{ localStorage.removeItem(SESSION_STORAGE_KEY); }catch(e){ /* 무시 */ } return false; }
  enterApp(user, true);
  return true;
}
function handleLogout(){
  SESSION = null;
  stopDbPolling();
  stopHeartbeat();
  stopHomeStatusWidget();
  stopScreensaverWatch();
  resetUiPrefsOnLogout();
  try{ localStorage.removeItem(SESSION_STORAGE_KEY); }catch(e){ /* 무시 */ }
  document.getElementById('app').classList.remove('active');
  document.getElementById('loginScreen').style.display='flex';
  document.getElementById('loginPw').value='';
  applyRememberedLoginId();
}

/* =========================================================================
   3z. 스크린세이버 (관리자가 시스템 관리에서 켜고 끌 수 있음, 기본 사용함)
   로그인 상태에서 마우스/키보드/스크롤/터치 활동이 10분간 없으면 전체화면
   오버레이를 띄우고, 클릭하면(활동 재개로 간주) 원래 화면으로 되돌린다.
   ========================================================================= */
const SCREENSAVER_IDLE_MS = 10 * 60 * 1000; // 10분
let screensaverTimer = null;
let screensaverActivityHandler = null;
const SCREENSAVER_ACTIVITY_EVENTS = ['mousemove','mousedown','keydown','scroll','touchstart'];
function resetScreensaverTimer(){
  if(!SESSION) return; // 로그인 화면에서는 동작하지 않는다
  if(screensaverTimer){ clearTimeout(screensaverTimer); screensaverTimer = null; }
  if(!DB || !DB.screensaverEnabled) return; // 관리자가 꺼두었으면 예약하지 않는다
  screensaverTimer = setTimeout(showScreensaverOverlay, SCREENSAVER_IDLE_MS);
}
function showScreensaverOverlay(){
  const el = document.getElementById('screensaverOverlay');
  if(el) el.style.display = 'flex';
}
function hideScreensaverOverlay(){
  const el = document.getElementById('screensaverOverlay');
  if(el) el.style.display = 'none';
}
// 스크린세이버 화면을 클릭하면 원래 화면으로 돌아가고, 다시 10분 카운트가 시작된다.
function dismissScreensaver(){
  hideScreensaverOverlay();
  resetScreensaverTimer();
}
function startScreensaverWatch(){
  if(screensaverActivityHandler) return; // 중복 등록 방지
  screensaverActivityHandler = ()=> resetScreensaverTimer();
  SCREENSAVER_ACTIVITY_EVENTS.forEach(ev=> document.addEventListener(ev, screensaverActivityHandler));
  resetScreensaverTimer();
}
function stopScreensaverWatch(){
  if(screensaverTimer){ clearTimeout(screensaverTimer); screensaverTimer = null; }
  if(screensaverActivityHandler){
    SCREENSAVER_ACTIVITY_EVENTS.forEach(ev=> document.removeEventListener(ev, screensaverActivityHandler));
    screensaverActivityHandler = null;
  }
  hideScreensaverOverlay();
}
// 시스템 관리 화면의 토글 스위치에서 호출 - 관리자만 사용 여부를 바꿀 수 있다.
function toggleScreensaverSetting(checked){
  if(!SESSION || SESSION.role!=='admin') return;
  DB.screensaverEnabled = !!checked;
  saveDB();
  if(DB.screensaverEnabled) resetScreensaverTimer();
  else stopScreensaverWatch();
  // 스위치 상태는 그대로 두고(재렌더링 없이) 안내 문구만 갱신되도록 다시 그린다.
  renderTab('systemAdmin');
}
// 모바일 상품권 취합 등록 일시 정지 스위치 - 관리자가 켜두면 지점 매니저 누구도 새 건을
// 등록할 수 없고, 등록 시도 시 안내 알림만 뜬다(페이지 자체는 그대로 유지, 등록만 막는다).
function toggleGiftcardLockSetting(checked){
  if(!SESSION || SESSION.role!=='admin') return;
  DB.giftcardRegistrationLocked = !!checked;
  saveDB();
  logActivity('update', `${SESSION.name}님(관리자)이 [모바일 상품권] 등록 ${DB.giftcardRegistrationLocked ? '일시 정지를 설정' : '정지를 해제'}했습니다`);
  renderTab('collectGiftcard');
}
function branchName(id){ const b=DB.branches.find(x=>x.id===id); return b?b.name:'-'; }
function updateNavVisibilityForRole(){
  const isAdmin = SESSION && SESSION.role==='admin';
  const g = document.getElementById('navSystemAdminGroup');
  const i = document.getElementById('navSystemAdminItem');
  if(g) g.style.display = isAdmin ? '' : 'none';
  if(i) i.style.display = isAdmin ? '' : 'none';
}

function showPwChangeBox(){
  document.getElementById('loginFormBox').style.display='none';
  document.getElementById('pwChangeBox').style.display='block';
  document.getElementById('pwcId').value=''; document.getElementById('pwcOld').value='';
  document.getElementById('pwcNew').value=''; document.getElementById('pwcNew2').value='';
  document.getElementById('pwcError').textContent=''; document.getElementById('pwcSuccess').textContent='';
}
function showLoginBox(){
  document.getElementById('pwChangeBox').style.display='none';
  document.getElementById('loginFormBox').style.display='block';
  document.getElementById('loginError').textContent='';
}
function handlePwChange(){
  const err = document.getElementById('pwcError');
  const ok = document.getElementById('pwcSuccess');
  err.textContent=''; ok.textContent='';
  if(!dbReady){ err.textContent='데이터를 아직 불러오는 중입니다. 잠시 후 다시 시도해 주세요.'; return; }
  const id = document.getElementById('pwcId').value.trim();
  const oldPw = document.getElementById('pwcOld').value.trim();
  const newPw = document.getElementById('pwcNew').value.trim();
  const newPw2 = document.getElementById('pwcNew2').value.trim();

  const user = DB.users.find(u=>u.empId===id && u.pw===oldPw);
  if(!user){ err.textContent='사번 또는 현재 비밀번호가 올바르지 않습니다.'; return; }
  if(newPw.length < 4){ err.textContent='새 비밀번호는 4자리 이상 입력해 주세요.'; return; }
  if(newPw !== newPw2){ err.textContent='새 비밀번호가 서로 일치하지 않습니다.'; return; }
  if(newPw === oldPw){ err.textContent='현재 비밀번호와 다른 비밀번호로 설정해 주세요.'; return; }

  user.pw = newPw;
  saveDB();
  ok.textContent='비밀번호가 변경되었습니다. 새 비밀번호로 로그인해 주세요.';
  document.getElementById('pwcOld').value=''; document.getElementById('pwcNew').value=''; document.getElementById('pwcNew2').value='';
}

/* =========================================================================
   3. APP STATE / NAV
   ========================================================================= */
const state = { tab:'home', viewBranchId:null };

// =========================================================================
// 3a. 사이드바 "New" 뱃지 — 게시형 메뉴에 내가 아직 안 본 새 글/등록이 있으면 표시
// DB.contentUpdatedAt[tabKey] = 해당 메뉴에 새 글이 등록될 때마다 갱신되는 타임스탬프
// DB.lastViewed[empId][tabKey] = 그 사용자가 해당 메뉴를 마지막으로 열어본 타임스탬프
// 두 값을 비교해서 "마지막으로 본 이후 새 글"이 있으면 뱃지를 띄운다.
// =========================================================================
const NEW_BADGE_TABS = [
  'notices','materials','infoReports','kakaoFriends',
  'eduHq','eduInhouse','eduEtc','eduVideo','eduTest','eduAiRp',
  'collectPhoto','collectGiftcard','collectContest','subTierContest',
  'mistakeNote','issueCase','bestPractice','policyQuiz',
  'suggestions'
];
// 시각(타임스탬프) 대신 전역 일련번호(seq)로 비교한다 - 같은 밀리초 안에 "새 글 등록"과
// "확인" 이 연달아 일어나도(자동화 테스트, 매우 빠른 클릭 등) 충돌 없이 정확히 비교된다.
function touchTabContent(tabKey){
  if(!DB.contentSeq) DB.contentSeq = 0;
  DB.contentSeq += 1;
  if(!DB.contentUpdatedAt) DB.contentUpdatedAt = {};
  DB.contentUpdatedAt[tabKey] = DB.contentSeq;
}
function tabHasNewContent(tabKey){
  if(!SESSION || !SESSION.empId) return false;
  const updated = DB.contentUpdatedAt && DB.contentUpdatedAt[tabKey];
  if(!updated) return false;
  const lastViewed = DB.lastViewed && DB.lastViewed[SESSION.empId] && DB.lastViewed[SESSION.empId][tabKey];
  if(lastViewed==null) return true;
  return updated > lastViewed;
}
function markTabViewed(tabKey){
  if(!SESSION || !SESSION.empId || !NEW_BADGE_TABS.includes(tabKey)) return;
  const wasNew = tabHasNewContent(tabKey);
  if(!DB.lastViewed) DB.lastViewed = {};
  if(!DB.lastViewed[SESSION.empId]) DB.lastViewed[SESSION.empId] = {};
  const updated = DB.contentUpdatedAt && DB.contentUpdatedAt[tabKey];
  DB.lastViewed[SESSION.empId][tabKey] = updated || 0;
  if(wasNew){ saveDB(true); }
  refreshNavBadges();
}
function refreshNavBadges(){
  document.querySelectorAll('.nav-item[data-tab]').forEach(el=>{
    const tab = el.dataset.tab;
    if(!NEW_BADGE_TABS.includes(tab)) return;
    let badge = el.querySelector('.nav-badge');
    const isNew = tabHasNewContent(tab);
    if(isNew && !badge){
      badge = document.createElement('span');
      badge.className = 'nav-badge';
      badge.textContent = 'New';
      el.appendChild(badge);
    } else if(!isNew && badge){
      badge.remove();
    }
  });
}

function navigateToTab(tab){
  document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));
  const target = document.querySelector('.nav-item[data-tab="'+tab+'"]');
  if(target) target.classList.add('active');
  markTabViewed(tab);
  renderTab(tab);
}
document.querySelectorAll('.nav-item[data-tab]').forEach(el=>{
  el.addEventListener('click', ()=>{
    navigateToTab(el.dataset.tab);
  });
});

