// 계정 수가 늘어날수록 시스템 관리 화면이 길어지는 것을 막기 위해, 계정 목록/수정/
// 비밀번호 관리/접속 기록은 "계정관리 상세" 버튼을 눌러야만 여는 별도 화면으로 분리했다.
// (시스템 관리 화면에는 DB 용량 최적화/신규 계정 생성/각종 업로드만 항상 보이도록 유지) - 2026.08
function renderAccountManagement(){
  if(!isSystemAdmin()){
    return `<div class="page-title">계정관리 상세</div><div class="page-desc">관리자만 접근할 수 있는 화면입니다.</div>`;
  }
  const editId = state.sysUserEditId || null;
  const sortedUsers = [...DB.users].sort((a,b)=>{
    if(a.role!==b.role){ const order={admin:0,exec:1,staff:2}; return order[a.role]-order[b.role]; }
    return branchName(a.branchId).localeCompare(branchName(b.branchId)) || String(a.name).localeCompare(String(b.name));
  });
  const userRows = sortedUsers.map(u=>{
    if(editId === u.empId){
      return `
      <tr>
        <td><input id="sueEmpId_${u.empId}" value="${escapeHtml(u.empId)}" style="width:100px"></td>
        <td><input id="sueName_${u.empId}" value="${escapeHtml(u.name)}" style="width:90px"></td>
        <td>${u.empId==='admin' ? '본사(전체)' : (u.role==='exec' ? '전 지점(조회 전용)' : `<select id="sueBranch_${u.empId}" style="width:130px">${branchOptionsHtml(u.branchId, true)}</select>`)}</td>
        <td><select id="sueRole_${u.empId}" style="width:90px" ${u.empId==='admin'?'disabled':''} onchange="syncEditUserBranchByRole('${u.empId}')">${roleOptionsHtml(u.role)}</select></td>
        <td><input id="suePw_${u.empId}" type="text" placeholder="변경 시에만 입력" style="width:110px"></td>
        <td class="muted" style="font-size:11px;">${loginHistoryLabel(u.empId)}</td>
        <td style="white-space:nowrap;">
          <button class="btn btn-sm btn-primary" onclick="saveEditSystemUser('${u.empId}')">저장</button>
          <button class="btn btn-sm" onclick="cancelEditSystemUser()">취소</button>
        </td>
      </tr>`;
    }
    return `
      <tr>
        <td class="muted">${escapeHtml(u.empId)}</td>
        <td>${escapeHtml(u.name)}</td>
        <td>${u.empId==='admin' ? '본사(전체)' : (u.role==='exec' ? '전 지점(조회 전용)' : branchName(u.branchId))}</td>
        <td><span class="badge ${u.role==='admin'?'good':(u.role==='exec'?'warn':'')}">${ROLE_LABELS[u.role]||u.role}</span></td>
        <td class="muted">${u.pw}</td>
        <td class="muted" style="font-size:11px;">${loginHistoryLabel(u.empId)}</td>
        <td style="white-space:nowrap;">
          <button class="btn btn-sm" onclick="startEditSystemUser('${u.empId}')">수정</button>
          <button class="btn btn-sm" onclick="resetSystemUserPw('${u.empId}')">비번 초기화</button>
          ${(u.empId==='admin' || u.empId===SESSION.empId) ? '' : `<button class="btn btn-sm" style="color:var(--bad);border-color:var(--bad);" onclick="deleteSystemUser('${u.empId}')">삭제</button>`}
        </td>
      </tr>`;
  }).join('');

  return `
    <button class="btn btn-sm" style="margin-bottom:10px;" onclick="renderTab('systemAdmin')">← 시스템 관리로 돌아가기</button>
    <div class="page-title">계정관리 상세</div>
    <div class="page-desc">현재 등록된 매니저/사원 전체 명단입니다. 사번·이름·지점명·직책을 직접 수정할 수 있고, 비밀번호는 초기화(1234)하거나 "수정"에서 새 비밀번호를 지정할 수 있습니다.</div>

    <div class="card">
      <table>
        <thead><tr><th>사번</th><th>이름</th><th>지점명</th><th>직책</th><th>비밀번호</th><th>접속 기록</th><th></th></tr></thead>
        <tbody>${userRows}</tbody>
      </table>
    </div>
  `;
}
function startEditSystemUser(empId){
  if(!isSystemAdmin()) return;
  state.sysUserEditId = empId;
  renderTab('accountManagement');
}
function cancelEditSystemUser(){
  state.sysUserEditId = null;
  renderTab('accountManagement');
}
function resetSystemUserPw(empId){
  if(!isSystemAdmin()) return;
  const u = DB.users.find(x=>x.empId===empId);
  if(!u) return;
  if(!confirm(`${u.name}(${u.empId}) 계정의 비밀번호를 1234로 초기화하시겠습니까?`)) return;
  u.pw = '1234';
  saveDB();
  renderTab('accountManagement');
}
function deleteSystemUser(empId){
  if(!isSystemAdmin()) return;
  const u = DB.users.find(x=>x.empId===empId);
  if(!u) return;
  if(empId==='admin'){ alert('기본 관리자 계정은 삭제할 수 없습니다.'); return; }
  if(SESSION.empId===empId){ alert('현재 로그인한 계정은 삭제할 수 없습니다.'); return; }
  if(!confirm(`"${u.name}"(${u.empId}) 계정을 삭제하시겠습니까?\n\n삭제해도 그동안 등록된 실적/게시물 등의 기록은 그대로 남고, 목표 배분 명단과 오늘 출근 명단에서만 제외됩니다.`)) return;
  DB.users = DB.users.filter(x=>x.empId!==empId);
  Object.values(DB.goals||{}).forEach(periods=>{
    Object.values(periods||{}).forEach(g=>{
      if(g && g.allocations) g.allocations = g.allocations.filter(a=>a.empId!==empId);
    });
  });
  Object.values(DB.attendance||{}).forEach(a=>{
    if(a && a.records) a.records = a.records.filter(r=>r.empId!==empId);
  });
  saveDB();
  renderTab('accountManagement');
}
// 공유 DB 전체 용량을 가늠해 관리자에게 미리 경고를 보여준다.
// (사진 첨부 누적으로 DB가 커지면서 저장/불러오기가 느려지거나 실패했던 문제 재발 방지 - 2026.08)
function dbCapacityGaugeHtml(){
  let sizeKB = 0;
  try{ sizeKB = Math.round(JSON.stringify(DB).length / 1024); }catch(e){ return ''; }
  const sizeLabel = sizeKB >= 1024 ? `${(sizeKB/1024).toFixed(1)}MB` : `${sizeKB}KB`;
  let level, color, msg;
  if(sizeKB < 5000){ level='good'; color='var(--good, #2e8b57)'; msg='정상'; }
  else if(sizeKB < 8000){ level='warn'; color='var(--warn, #c98a00)'; msg='주의 - 용량이 늘고 있습니다. 압축을 권장합니다.'; }
  else { level='bad'; color='var(--bad, #c0392b)'; msg='위험 - 저장/불러오기 오류가 발생할 수 있습니다. 지금 압축을 실행해 주세요.'; }
  return `
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:2px;">
      <span class="muted" style="font-size:12.5px;">현재 DB 용량</span>
      <b style="font-size:13.5px;color:${color};">${sizeLabel}</b>
      <span style="font-size:11.5px;color:${color};">· ${msg}</span>
    </div>`;
}
// 공유 DB에 이미 저장되어 있는 사진들을 화질은 유지한 채 용량만 줄여서 재저장한다.
// (사진 첨부가 누적되어 DB가 커지면서 저장/불러오기가 느려지거나 실패하는 문제 대응 - 2026.08)
function collectDbImageTargets(){
  const targets = [];
  (DB.execPhotos||[]).forEach(r=>(r.photos||[]).forEach(f=>{ if(f && f.dataUrl) targets.push({get:()=>f.dataUrl, set:v=>{f.dataUrl=v;}}); }));
  (DB.giftcardRequests||[]).forEach(r=>(r.receipts||[]).forEach(f=>{ if(f && f.dataUrl) targets.push({get:()=>f.dataUrl, set:v=>{f.dataUrl=v;}}); }));
  (DB.notices||[]).forEach(n=>(n.attachments||[]).forEach(f=>{ if(f && f.dataUrl) targets.push({get:()=>f.dataUrl, set:v=>{f.dataUrl=v;}}); }));
  (DB.infoReports||[]).forEach(r=>(r.attachments||[]).forEach(f=>{ if(f && f.dataUrl) targets.push({get:()=>f.dataUrl, set:v=>{f.dataUrl=v;}}); }));
  (DB.bestPractices||[]).forEach(p=>(p.attachments||[]).forEach(f=>{ if(f && f.dataUrl) targets.push({get:()=>f.dataUrl, set:v=>{f.dataUrl=v;}}); }));
  (DB.issueCases||[]).forEach(p=>(p.attachments||[]).forEach(f=>{ if(f && f.dataUrl) targets.push({get:()=>f.dataUrl, set:v=>{f.dataUrl=v;}}); }));
  (DB.suggestions||[]).forEach(s=>{ if(s.attachmentDataUrl) targets.push({get:()=>s.attachmentDataUrl, set:v=>{s.attachmentDataUrl=v;}}); });
  (DB.contestGifts||[]).forEach(r=>(r.evidenceFiles||[]).forEach(f=>{ if(f && f.dataUrl) targets.push({get:()=>f.dataUrl, set:v=>{f.dataUrl=v;}}); }));
  (DB.subTierContestGifts||[]).forEach(r=>(r.evidenceFiles||[]).forEach(f=>{ if(f && f.dataUrl) targets.push({get:()=>f.dataUrl, set:v=>{f.dataUrl=v;}}); }));
  return targets;
}
async function optimizeDbImages(){
  if(!isSystemAdmin()) return;
  const statusEl = document.getElementById('dbOptStatus');
  function setStatus(msg){ if(statusEl) statusEl.textContent = msg; }
  const targets = collectDbImageTargets().filter(t=>{
    const v = t.get();
    return v && /^data:image\//i.test(v) && !/^data:image\/gif/i.test(v);
  });
  if(targets.length===0){ setStatus('압축할 사진이 없습니다.'); return; }
  if(!confirm(`저장된 사진 ${targets.length}장을 압축합니다. 사진이 많으면 1~2분 정도 걸릴 수 있습니다. 진행하시겠습니까?`)) return;
  let done=0, shrunk=0, before=0, after=0;
  for(const t of targets){
    const orig = t.get();
    before += orig.length;
    try{
      const compressed = await compressImageDataUrl(orig, 1600, 0.72);
      if(compressed && compressed.length < orig.length){ t.set(compressed); shrunk++; after += compressed.length; }
      else { after += orig.length; }
    }catch(e){ after += orig.length; }
    done++;
    if(done % 5 === 0 || done===targets.length) setStatus(`압축 중... (${done}/${targets.length})`);
  }
  setStatus('저장 중...');
  try{
    await pushDBToServer();
    const savedKB = Math.max(0, Math.round((before-after)/1024));
    setStatus(`완료: 사진 ${shrunk}/${targets.length}장을 압축해 약 ${savedKB.toLocaleString()}KB 절약했습니다.`);
    const gaugeEl = document.getElementById('dbCapacityGauge');
    if(gaugeEl) gaugeEl.innerHTML = dbCapacityGaugeHtml();
  }catch(e){
    setStatus('사진 압축은 완료했지만 저장 중 오류가 발생했습니다. 다시 시도해 주세요.');
  }
}
function syncNewUserBranchByRole(){
  const roleSel = document.getElementById('suNewRole');
  const branchSel = document.getElementById('suNewBranch');
  if(!roleSel || !branchSel) return;
  if(roleSel.value==='admin' || roleSel.value==='exec'){
    branchSel.value = '';
    branchSel.disabled = true;
  }else{
    branchSel.disabled = false;
    if(!branchSel.value) branchSel.value = DB.branches[0] ? DB.branches[0].id : '';
  }
}
function syncEditUserBranchByRole(empId){
  const roleSel = document.getElementById('sueRole_'+empId);
  const branchSel = document.getElementById('sueBranch_'+empId);
  if(!roleSel || !branchSel) return;
  if(roleSel.value==='admin' || roleSel.value==='exec'){
    branchSel.value = '';
    branchSel.disabled = true;
  }else{
    branchSel.disabled = false;
    if(!branchSel.value) branchSel.value = DB.branches[0] ? DB.branches[0].id : '';
  }
}
function createSystemUser(){
  if(!isSystemAdmin()) return;
  const msgEl = document.getElementById('suNewMsg');
  const empId = document.getElementById('suNewEmpId').value.trim();
  const name = document.getElementById('suNewName').value.trim();
  const branchIdRaw = document.getElementById('suNewBranch').value;
  const role = document.getElementById('suNewRole').value;
  if(!empId || !name){ msgEl.textContent = '사번과 이름을 입력해 주세요.'; return; }
  if(DB.users.find(u=>u.empId===empId)){ msgEl.textContent = '이미 존재하는 사번입니다.'; return; }
  const branchId = (role==='admin' || role==='exec' || !branchIdRaw) ? null : branchIdRaw;
  DB.users.push({empId, pw:'1234', name, role, branchId});
  if(role!=='admin' && role!=='exec' && branchId){
    const g = getGoals(branchId, currentGoalsPeriod());
    if(g && !g.allocations.find(a=>a.empId===empId)) g.allocations.push({empId, name, target:0, subQtyTarget:0, subAmtTarget:0});
    const att = DB.attendance[branchId];
    if(att && !att.records.find(r=>r.empId===empId)) att.records.push({empId, name, status:'출근', checkin:'09:00', checkout:'18:00'});
  }
  saveDB();
  msgEl.innerHTML = `<span style="color:var(--good);">계정이 생성되었습니다: ${escapeHtml(name)}(${escapeHtml(empId)}), 초기 비밀번호 1234${role==='admin'?' · 관리자 권한 부여됨':(role==='exec'?' · 임원(전 지점 조회 전용) 권한 부여됨':'')}</span>`;
  renderTab('systemAdmin');
}
function saveEditSystemUser(oldEmpId){
  if(!isSystemAdmin()) return;
  const u = DB.users.find(x=>x.empId===oldEmpId);
  if(!u) return;
  const newEmpId = document.getElementById('sueEmpId_'+oldEmpId).value.trim();
  const newName = document.getElementById('sueName_'+oldEmpId).value.trim();
  const newRole = oldEmpId==='admin' ? u.role : document.getElementById('sueRole_'+oldEmpId).value;
  const branchSel = document.getElementById('sueBranch_'+oldEmpId);
  const newBranch = branchSel ? branchSel.value : u.branchId;
  const newPw = document.getElementById('suePw_'+oldEmpId).value.trim();
  if(!newEmpId || !newName){ alert('사번과 이름을 입력해 주세요.'); return; }
  if(newEmpId !== oldEmpId && DB.users.find(x=>x.empId===newEmpId)){ alert('이미 존재하는 사번입니다.'); return; }

  if(newEmpId !== oldEmpId){
    renameEmpIdEverywhere(oldEmpId, newEmpId);
    u.empId = newEmpId;
  }
  u.name = newName;
  u.role = newRole;
  u.branchId = (newRole==='admin' || newRole==='exec' || !newBranch) ? null : newBranch;
  if(newPw) u.pw = newPw;

  state.sysUserEditId = null;
  saveDB();
  renderTab('accountManagement');
}

/* =========================================================================
   6a. NOTICE BANNER (공지사항 - 관리자만 작성/수정, 자동 롤링 배너)
   ========================================================================= */
let noticeTimer = null;
function escapeHtml(s){
  return String(s==null?'':s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function sortedNotices(){
  return [...DB.notices].sort((a,b)=> b.createdAt.localeCompare(a.createdAt));
}
function renderNoticeBanner(){
  const isAdmin = SESSION.role==='admin';
  if(!state.noticeIndex) state.noticeIndex = 0;
  if(state.noticeFormOpen===undefined) state.noticeFormOpen = false;
  if(state.noticeEditId===undefined) state.noticeEditId = null;

  const notices = sortedNotices();
  const adminControls = isAdmin ? `
    <div class="nb-controls">
      <button class="nb-admin-btn" onclick="openNoticeForm()">+ 공지 작성</button>
      ${notices.length>0 ? `<button class="nb-admin-btn" onclick="editCurrentNotice()">수정</button><button class="nb-admin-btn" onclick="deleteCurrentNotice()">삭제</button>` : ''}
    </div>` : '';

  const bodyHtml = notices.length===0
    ? `<div class="nb-empty">등록된 공지사항이 없습니다.${isAdmin ? ' 상단의 "+ 공지 작성"으로 새 공지를 올려보세요.' : ''}</div>`
    : noticeBodyHtml(notices[state.noticeIndex % notices.length]);

  const dotsHtml = notices.length>1 ? `
    <div class="nb-dots">
      ${notices.map((n,i)=>`<span class="nb-dot ${i===(state.noticeIndex%notices.length)?'active':''}" onclick="goToNotice(${i})"></span>`).join('')}
    </div>` : '';

  const navHtml = notices.length>1 ? `
      <button class="nb-nav-btn" onclick="shiftNotice(-1)" style="position:absolute;left:10px;top:50%;transform:translateY(-50%);">◀</button>
      <button class="nb-nav-btn" onclick="shiftNotice(1)" style="position:absolute;right:10px;top:50%;transform:translateY(-50%);">▶</button>` : '';

  return `
    <div class="card notice-banner" style="${notices.length>1?'padding-left:40px;padding-right:40px;':''}">
      <div class="nb-label">📢 공지사항</div>
      ${adminControls}
      <div id="noticeBannerBody">${bodyHtml}</div>
      ${dotsHtml}
      ${navHtml}
    </div>
    ${state.noticeFormOpen ? renderNoticeForm() : ''}
  `;
}
function isImageAttachment(f){
  const v = (f && f.dataUrl) || '';
  if(/^data:image\//i.test(v)) return true;
  // Storage로 옮겨진 사진은 base64가 아니라 URL로 저장되므로 확장자로 판별한다.
  if(/^https?:\/\//i.test(v) && /\.(png|jpe?g|gif|webp|bmp|avif)(\?|#|$)/i.test(v)) return true;
  // 업로드 당시 휴대폰 등에서 MIME 정보가 유실되어 URL 확장자가 .bin 등으로 저장된 경우를 대비해
  // 원본 파일명 확장자로도 한 번 더 확인한다 (예: KakaoTalk_2026...jpg).
  const name = (f && f.name) || '';
  if(/\.(png|jpe?g|gif|webp|bmp|avif)$/i.test(name)) return true;
  return false;
}
/* =========================================================================
   6a0. 게시글 작성용 리치 텍스트 에디터 (공지사항/정보보고/각종 취합 공지/
   우수 활동 사례/이슈제품 판매 성공 사례 등 여러 게시판이 공통으로 사용)
   - contenteditable 기반, document.execCommand로 굵게/기울임/색상/정렬 등 처리
   - 저장 시 innerHTML(=HTML)을 그대로 보관하고, 읽기 화면에서는 richContentHtml()로
     출력한다. 과거(플레인 텍스트로 저장된) 게시글도 태그가 없으면 그대로 줄바꿈만
     살려서 보여주므로 기존 데이터는 깨지지 않는다.
   ========================================================================= */
const richSavedRange = {};
function richSaveSelection(id){
  const sel = window.getSelection();
  if(sel && sel.rangeCount>0){
    const range = sel.getRangeAt(0);
    const el = document.getElementById(id);
    if(el && el.contains(range.commonAncestorContainer)) richSavedRange[id] = range.cloneRange();
  }
}
function richRestoreSelection(id){
  const range = richSavedRange[id];
  if(!range) return;
  const sel = window.getSelection();
  sel.removeAllRanges();
  sel.addRange(range);
}
function richExec(id, cmd, value){
  const el = document.getElementById(id);
  if(!el) return;
  el.focus();
  richRestoreSelection(id);
  document.execCommand(cmd, false, value===undefined ? null : value);
  richSaveSelection(id);
}
// HSL -> HEX 변환(팔레트 그리드를 색상별로 계산해서 만들기 위함 — hex 50여개를 직접 나열하지
// 않고 색상환을 고르게 나눈 값으로 생성한다).
function richHslToHex(h, s, l){
  s/=100; l/=100;
  const k = n => (n + h/30) % 12;
  const a = s * Math.min(l, 1-l);
  const f = n => l - a*Math.max(-1, Math.min(k(n)-3, Math.min(9-k(n), 1)));
  const toHex = x => Math.round(x*255).toString(16).padStart(2,'0');
  return `#${toHex(f(0))}${toHex(f(8))}${toHex(f(4))}`;
}
// 구글 문서 글자색 팔레트와 비슷하게: 맨 윗줄은 무채색(검정~흰색), 그 아래는 색상 10가지 ×
// 밝기 5단계 그리드. 스와치를 클릭하면 별도 "적용" 버튼 없이 바로 그 색이 적용된다.
function richColorPaletteHtml(id){
  const grays = ['#000000','#434343','#666666','#999999','#b7b7b7','#cccccc','#d9d9d9','#efefef','#f3f3f3','#ffffff'];
  const hues = [0,25,45,65,150,180,205,230,265,320];
  const lightness = [85,70,55,42,28];
  const swatch = c => `<button type="button" onmousedown="event.preventDefault()" class="rt-swatch" style="background:${c};" onclick="richApplyPaletteColor('${id}','${c}')" title="${c}"></button>`;
  let html = `<div class="rt-palette-row">${grays.map(swatch).join('')}</div>`;
  lightness.forEach(l=>{
    html += `<div class="rt-palette-row">${hues.map(h=>swatch(richHslToHex(h,65,l))).join('')}</div>`;
  });
  return html;
}
let richPaletteOutsideHandler = null;
function richToggleColorPalette(id){
  const el = document.getElementById(id+'_colorPalette');
  if(!el) return;
  const opening = el.style.display !== 'block';
  document.querySelectorAll('.rt-color-palette').forEach(p=>{ p.style.display = 'none'; });
  if(richPaletteOutsideHandler){ document.removeEventListener('mousedown', richPaletteOutsideHandler); richPaletteOutsideHandler = null; }
  if(opening){
    el.style.display = 'block';
    richPaletteOutsideHandler = function(e){
      const btn = document.getElementById(id+'_colorBtn');
      if(!el.contains(e.target) && e.target!==btn && !(btn && btn.contains(e.target))){
        el.style.display = 'none';
        document.removeEventListener('mousedown', richPaletteOutsideHandler);
        richPaletteOutsideHandler = null;
      }
    };
    setTimeout(()=>document.addEventListener('mousedown', richPaletteOutsideHandler), 0);
  }
}
function richApplyPaletteColor(id, color){
  richExec(id, 'foreColor', color);
  const el = document.getElementById(id+'_colorPalette');
  if(el) el.style.display = 'none';
  if(richPaletteOutsideHandler){ document.removeEventListener('mousedown', richPaletteOutsideHandler); richPaletteOutsideHandler = null; }
}
function richSetFontSize(id, px){
  const el = document.getElementById(id);
  if(!el) return;
  el.focus();
  richRestoreSelection(id);
  document.execCommand('fontSize', false, '7');
  el.querySelectorAll('font[size="7"]').forEach(f=>{
    const span = document.createElement('span');
    span.style.fontSize = px+'px';
    while(f.firstChild) span.appendChild(f.firstChild);
    f.parentNode.replaceChild(span, f);
  });
  richSaveSelection(id);
}
