      <td><select id="gceTransferBranch_${r.id}" style="width:120px"><option value="NONE" ${(r.transferBranchId==='NONE'||!r.transferBranchId)?'selected':''}>해당없음</option>${branchOptionsHtml(r.transferBranchId)}</select></td>
