function afterRenderHooks(tab){
  if(tab==='home') startNoticeRotation();
  if(tab==='home') startHomeStatusWidget(); else stopHomeStatusWidget();
  if(tab==='accountManagement') loadLoginStatsIfNeeded();
  if(tab==='systemAdmin') refreshConflictLog();
  updateInventoryNavLabel();
  enableDragDropForFileInputs();
  updateExportToolbarVisibility(tab);
  refreshNavBadges();
  applyReadOnlyLockdown();
}
// 임원(조회 전용) 계정은 saveDB()에서도 이중으로 막혀 있지만, 등록/저장/삭제 등 버튼을 눌렀을 때
// "왜 안 되는지" 바로 알 수 있도록 화면에 렌더링될 때마다 그런 버튼들을 눈에 띄게 비활성화한다.
// 지점 선택 pill/필터 드롭다운/검색창/페이지 이동 등 "조회" 관련 조작은 그대로 남겨두고,
// 버튼 문구에 아래 변경 관련 단어가 포함된 <button>만 골라 막는다(간단하지만 이 사이트 전체가
// 등록/저장/삭제/수정 같은 한국어 문구를 매우 일관되게 써서 커버리지가 높다).
const READONLY_LOCKDOWN_WORDS = ['등록','저장','삭제','수정','추가','생성','초기화','업로드','발송','승인','반영','재발급','변경'];
function applyReadOnlyLockdown(){
  const main = document.getElementById('mainContent');
  if(!main || !SESSION || SESSION.role!=='exec') return;
  const msg = '임원(조회 전용) 계정은 등록/수정/삭제 기능을 사용할 수 없습니다. 조회만 가능합니다.';
  main.querySelectorAll('button').forEach(btn=>{
    const text = (btn.textContent||'').trim();
    if(!text || !READONLY_LOCKDOWN_WORDS.some(w=>text.includes(w))) return;
    btn.disabled = true;
    btn.title = msg;
    btn.style.opacity = '.45';
    btn.style.cursor = 'not-allowed';
    btn.onclick = function(e){ if(e){ e.preventDefault(); e.stopPropagation(); } alert(msg); return false; };
  });
  main.querySelectorAll('input[type=file]').forEach(inp=>{ inp.disabled = true; inp.title = msg; });
}
function updateExportToolbarVisibility(tab){
  const el = document.getElementById('exportToolbar');
  if(!el) return;
  el.style.display = '';
  const isPhotoAdmin = (tab==='collectPhoto' && SESSION && SESSION.role==='admin');
  const photoBtn = document.getElementById('execPhotoDownloadBtn');
  if(photoBtn) photoBtn.style.display = isPhotoAdmin ? '' : 'none';
  const dlSelBtn = document.getElementById('execPhotoDownloadSelectedBtn');
  const delSelBtn = document.getElementById('execPhotoDeleteSelectedBtn');
  if(dlSelBtn) dlSelBtn.style.display = isPhotoAdmin ? '' : 'none';
  if(delSelBtn) delSelBtn.style.display = isPhotoAdmin ? '' : 'none';
  // 실행력 점검 사진 화면을 벗어나면 이전에 체크해 둔 선택 상태가 계속 남아있지 않도록 비운다.
  if(!isPhotoAdmin && state.epSelectedIds) state.epSelectedIds.clear();
  updateExecPhotoSelectionToolbar();

  // 모바일 상품권/구독연동사은품/기타 사은품 취합 - 관리자가 체크박스로 여러 건을 선택해
  // 한 번에 삭제하는 버튼도 실행력 점검 사진과 동일한 패턴으로 해당 화면+관리자일 때만 보인다.
  const isGcAdmin = (tab==='collectGiftcard' && SESSION && SESSION.role==='admin');
  const gcDelBtn = document.getElementById('gcDeleteSelectedBtn');
  if(gcDelBtn) gcDelBtn.style.display = isGcAdmin ? '' : 'none';
  if(!isGcAdmin && state.gcSelectedIds) state.gcSelectedIds.clear();
  updateGiftcardSelectionToolbar();

  const isCgAdmin = (tab==='collectContest' && SESSION && SESSION.role==='admin');
  const cgDelBtn = document.getElementById('cgDeleteSelectedBtn');
  if(cgDelBtn) cgDelBtn.style.display = isCgAdmin ? '' : 'none';
  if(!isCgAdmin && state.cgSelectedIds) state.cgSelectedIds.clear();
  updateContestGiftSelectionToolbar();

  const isStcAdmin = (tab==='subTierContest' && SESSION && SESSION.role==='admin');
  const stcDelBtn = document.getElementById('stcDeleteSelectedBtn');
  if(stcDelBtn) stcDelBtn.style.display = isStcAdmin ? '' : 'none';
  if(!isStcAdmin && state.stcSelectedIds) state.stcSelectedIds.clear();
  updateSubTierContestSelectionToolbar();
}
function updateInventoryNavLabel(){
  const el = document.getElementById('navInventoryDate');
  if(el) el.textContent = todayStr() + ' 기준';
}

/* =========================================================================
   9k. 전체 검색 (사이드바/모바일 상단) - 공지사항/정보보고/오답노트/우수 활동 사례/
   이슈제품 성공사례/가망고객/지점/계정을 한 번에 검색해 해당 화면으로 바로 이동한다.
   각 게시판은 이미 자체 검색(applyBoardSearchAndPaging)이 있으므로, 게시판 결과를 클릭하면
   그 화면으로 이동하면서 같은 검색어로 자동 필터링까지 해준다(setBoardSearch 재사용).
   ========================================================================= */
function globalSearchResults(query){
  const q = String(query||'').trim();
  if(!q || !SESSION) return [];
  const qLower = q.toLowerCase();
  const includes = (text)=> String(text||'').toLowerCase().includes(qLower);
  const results = [];

  (DB.notices||[]).forEach(n=>{
    const text = `${n.title||''} ${richStripTags(n.content)} ${n.author||''}`;
    if(includes(text)) results.push({type:'notice', id:n.id, icon:'📢', cat:'공지사항', title:n.title||'(제목 없음)', sub:(n.createdAt||'').slice(0,10)});
  });
  (DB.materials||[]).forEach(n=>{
    const text = `${n.title||''} ${richStripTags(n.content)} ${n.author||''}`;
    if(includes(text)) results.push({type:'material', id:n.id, icon:'📁', cat:'각종 자료', title:n.title||'(제목 없음)', sub:(n.createdAt||'').slice(0,10)});
  });
  (DB.infoReports||[]).forEach(r=>{
    const text = `${r.title||''} ${richStripTags(r.content)} ${r.authorName||''} ${branchName(r.branchId)||''}`;
    if(includes(text)) results.push({type:'infoReport', id:r.id, icon:'📄', cat:'정보보고', title:r.title||'(제목 없음)', sub:branchName(r.branchId)||''});
  });
  if(SESSION.role==='admin' || SESSION.role==='exec'){
    (DB.mistakeNotes||[]).forEach(n=>{
      const text = `${branchName(n.branchId)||''} ${n.authorName||''} ${n.category||''} ${n.model||''} ${n.content||''}`;
      if(includes(text)) results.push({type:'mistakeNote', id:n.id, icon:'📝', cat:'오답노트', title:n.model||n.category||'오답노트', sub:branchName(n.branchId)||''});
    });
  }
  (DB.bestPractices||[]).forEach(p=>{
    const text = `${p.title||''} ${richStripTags(p.content)} ${p.activityResult||''} ${p.managerName||''} ${bpBranchDisplayName(p.branchId)||''} ${p.authorName||''}`;
    if(includes(text)) results.push({type:'bestPractice', id:p.id, icon:'🏆', cat:'우수 활동 사례', title:p.title||'(제목 없음)', sub:bpBranchDisplayName(p.branchId)||''});
  });
  (DB.issueCases||[]).forEach(p=>{
    const text = `${p.title||''} ${richStripTags(p.content)} ${p.activityResult||''} ${p.managerName||''} ${bpBranchDisplayName(p.branchId)||''} ${p.authorName||''}`;
    if(includes(text)) results.push({type:'issueCase', id:p.id, icon:'💡', cat:'이슈제품 성공사례', title:p.title||'(제목 없음)', sub:bpBranchDisplayName(p.branchId)||''});
  });
  (visibleProspects()||[]).forEach(p=>{
    const text = `${p.name||''} ${p.phone||''}`;
    if(includes(text)) results.push({type:'prospect', id:p.id, icon:'🧑', cat:'가망고객', title:p.name||'(이름 없음)', sub:p.phone||''});
  });
  if(canSwitchBranch()){
    (DB.branches||[]).forEach(b=>{
      if(includes(b.name)) results.push({type:'branch', id:b.id, icon:'🏬', cat:'지점', title:b.name, sub:'목표관리로 이동'});
    });
  }
  if(SESSION.role==='admin'){
    (DB.users||[]).forEach(u=>{
      const text = `${u.name||''} ${u.empId||''}`;
      if(includes(text)) results.push({type:'user', id:u.empId, icon:'👤', cat:'계정', title:u.name||u.empId, sub:`${u.empId} · ${ROLE_LABELS[u.role]||u.role}`});
    });
  }
  return results.slice(0, 25);
}
function globalSearchResultsHtml(query){
  const q = String(query||'').trim();
  if(!q) return '';
  const results = globalSearchResults(q);
  if(results.length===0) return `<div class="muted" style="padding:14px;font-size:12px;">"${escapeHtml(q)}"에 대한 검색 결과가 없습니다.</div>`;
  return results.map(r=>`
    <div class="gs-result-item" onclick="goToGlobalSearchResult('${r.type}','${String(r.id).replace(/'/g,"")}')">
      <span class="gs-result-icon">${r.icon}</span>
      <div class="gs-result-text">
        <div class="gs-result-title">${escapeHtml(r.title)}</div>
        <div class="gs-result-sub">${escapeHtml(r.cat)}${r.sub ? ' · ' + escapeHtml(r.sub) : ''}</div>
      </div>
    </div>`).join('');
}
// 검색창이 비어있을 때(포커스만 준 상태)는 결과 대신 최근 검색어를 보여준다.
// 매번 같은 모델명/지점명을 다시 타이핑하지 않도록 최근 5개까지 기억한다.
const RECENT_SEARCHES_MAX = 5;
function recordRecentSearch(term){
  const t = String(term||'').trim();
  if(!t || !state.uiPrefs) return;
  if(!state.uiPrefs.recentSearches) state.uiPrefs.recentSearches = [];
  const list = state.uiPrefs.recentSearches.filter(x=>x !== t);
  list.unshift(t);
  state.uiPrefs.recentSearches = list.slice(0, RECENT_SEARCHES_MAX);
  saveUiPrefs();
}
function removeRecentSearch(term){
  if(!state.uiPrefs || !state.uiPrefs.recentSearches) return;
  state.uiPrefs.recentSearches = state.uiPrefs.recentSearches.filter(x=>x !== term);
  saveUiPrefs();
  const input = document.getElementById('globalSearchInput');
  handleGlobalSearchInput(input ? input.value : '');
}
function applyRecentSearch(term){
  const input = document.getElementById('globalSearchInput');
  if(input){ input.value = term; input.focus(); }
  handleGlobalSearchInput(term);
}
function recentSearchesHtml(){
  const list = (state.uiPrefs && state.uiPrefs.recentSearches) || [];
  if(list.length === 0) return '';
  return '<div class="gs-recent-label">최근 검색어</div>' +
    list.map(t=>`<div class="gs-recent-item" data-term="${escapeHtml(t)}">
      <span class="gs-recent-icon">🕘</span><span class="gs-recent-text">${escapeHtml(t)}</span>
      <span class="gs-recent-remove" data-term="${escapeHtml(t)}" title="삭제">×</span>
    </div>`).join('');
}
function wireRecentSearchItems(container){
  container.querySelectorAll('.gs-recent-item').forEach(el=>{
    el.addEventListener('click', ()=> applyRecentSearch(el.dataset.term));
  });
  container.querySelectorAll('.gs-recent-remove').forEach(el=>{
    el.addEventListener('click', e=>{
      e.stopPropagation();
      removeRecentSearch(el.dataset.term);
    });
  });
}
function handleGlobalSearchInput(value){
  const q = String(value||'').trim();
  document.querySelectorAll('.gs-dropdown').forEach(d=>{
    if(!q){
      const html = recentSearchesHtml();
      d.innerHTML = html;
      d.style.display = html ? 'block' : 'none';
      wireRecentSearchItems(d);
    } else {
      d.style.display = 'block';
      d.innerHTML = globalSearchResultsHtml(value);
    }
  });
}
function closeGlobalSearch(){
  document.querySelectorAll('.gs-dropdown').forEach(d=>{ d.style.display = 'none'; });
}
function goToGlobalSearchResult(type, id){
  const input = document.getElementById('globalSearchInput');
  const q = input ? input.value : '';
  recordRecentSearch(q);
  closeGlobalSearch();
  if(type==='notice') setBoardSearch('notice', 'notices', q);
  else if(type==='material') setBoardSearch('material', 'materials', q);
  else if(type==='infoReport') setBoardSearch('infoReport', 'infoReports', q);
  else if(type==='mistakeNote') setBoardSearch('mistakeNote', 'mistakeNote', q);
  else if(type==='bestPractice') setBoardSearch('bestPractice', 'bestPractice', q);
  else if(type==='issueCase') setBoardSearch('issueCase', 'issueCase', q);
  else if(type==='prospect'){ state.prospectFilterBranchId = null; state.prospectFilterEmpId = null; renderTab('prospects'); }
  else if(type==='branch'){ state.viewBranchId = id; state.homeAttBranchId = null; renderTab('goals'); }
  else if(type==='user') renderTab('accountManagement');
  const mobileBar = document.getElementById('mobileSearchBar');
  if(mobileBar) mobileBar.style.display = 'none';
}
function toggleMobileGlobalSearch(){
  const bar = document.getElementById('mobileSearchBar');
  if(!bar) return;
  const showing = bar.style.display === 'block';
  bar.style.display = showing ? 'none' : 'block';
  if(!showing){
    const input = document.getElementById('globalSearchInput');
    if(input){ input.value=''; input.focus(); }
    const dd = document.getElementById('globalSearchDropdown');
    if(dd){ dd.style.display='none'; dd.innerHTML=''; }
  }
}
document.addEventListener('click', function(e){
  if(!e.target.closest('.gs-wrap') && !e.target.closest('.mt-search-toggle')) closeGlobalSearch();
});
document.addEventListener('keydown', function(e){
  if(e.key==='Escape') closeGlobalSearch();
});

(async function initApp(){
  await loadDB();
  updateInventoryNavLabel();
  // 새로고침해도 로그인 상태가 유지되도록, 저장된 세션이 있으면 로그인 화면을 건너뛰고 바로 복원한다.
  const restored = restoreSessionIfAny();
  if(!restored) applyRememberedLoginId();
  const overlay = document.getElementById('loginLoadingOverlay');
  if(overlay) overlay.style.display = 'none';
})();
document.getElementById('loginPw').addEventListener('keydown', e=>{ if(e.key==='Enter') handleLogin(); });
